// --- trace parsing ------------------------------------------------------------------------------

export type SimStep = {
  line: number;
  kind: string;
  pid: number; // open (the session's process), spawn, exit, kill
  sid: string;
  mode: string;
  sql: string;
  params: Map<string, string>;
};

export type SimTrace = { header: Map<string, string>; steps: SimStep[] };

export function parseTrace(text: string): SimTrace {
  const tr: SimTrace = { header: new Map(), steps: [] };
  const lines = text.split("\n");
  for (let n = 0; n < lines.length; n++) {
    let line = lines[n]!;
    while (line.endsWith("\r")) line = line.slice(0, -1);
    if (trimSpace(line) === "") continue;
    if (line.startsWith("#")) {
      const body = trimSpace(line.slice(1));
      const colon = body.indexOf(":");
      if (colon >= 0) {
        tr.header.set(trimSpace(body.slice(0, colon)), trimSpace(body.slice(colon + 1)));
      }
      continue;
    }
    const f = fields(line);
    const st: SimStep = {
      line: n + 1,
      kind: f[0]!,
      pid: 0,
      sid: "",
      mode: "",
      sql: "",
      params: new Map(),
    };
    switch (st.kind) {
      case "open":
        if (f.length !== 3 && f.length !== 4) {
          throw new Error(`line ${n + 1}: open <sid> read|write [p<N>]`);
        }
        st.sid = f[1]!;
        st.mode = f[2]!;
        if (f.length === 4) st.pid = parsePid(f[3]!, n + 1);
        break;
      case "spawn":
      case "exit":
      case "kill":
      case "disconnect":
        if (f.length !== 2) throw new Error(`line ${n + 1}: ${st.kind} p<N>`);
        st.pid = parsePid(f[1]!, n + 1);
        break;
      case "on": {
        if (f.length < 3) throw new Error(`line ${n + 1}: on <sid> <sql>`);
        st.sid = f[1]!;
        const rest = trimSpace(line.slice("on".length));
        st.sql = trimSpace(rest.slice(st.sid.length));
        break;
      }
      case "commit":
      case "rollback":
      case "close":
        if (f.length !== 2) throw new Error(`line ${n + 1}: ${st.kind} <sid>`);
        st.sid = f[1]!;
        break;
      case "fault":
      case "crash":
        if (f.length < 2) throw new Error(`line ${n + 1}: ${st.kind} <kind> [k=v ...]`);
        st.mode = f[1]!;
        parseParams(st, f.slice(2), n + 1);
        break;
      case "clock":
        if (f.length !== 2 || !f[1]!.startsWith("+")) {
          throw new Error(`line ${n + 1}: clock +<micros>`);
        }
        st.params.set("delta", f[1]!.slice(1));
        break;
      case "attach":
        if (f.length !== 2 || f[1] === "main" || f[1] === "temp") {
          throw new Error(`line ${n + 1}: attach <name>`);
        }
        st.sid = f[1]!;
        break;
      case "compact":
        if (f.length > 2) throw new Error(`line ${n + 1}: compact [<database>]`);
        st.sid = f.length === 2 ? f[1]! : "main";
        break;
      case "change_key":
      case "rekey": {
        // S12–S13: a credential change or rekey of main (or a file attachment) to simulation key 1–3,
        // or a rekey that decrypts it.
        let ok = f.length === 2 || (f.length === 3 && f[2] !== "temp");
        ok = ok && (["1", "2", "3"].includes(f[1]!) || (f[1] === "plain" && st.kind === "rekey"));
        if (!ok) throw new Error(`line ${n + 1}: ${st.kind} 1|2|3|plain [<database>]`);
        st.mode = f[1]!;
        st.sid = f.length === 3 ? f[2]! : "main";
        break;
      }
      case "replay":
        if (f.length !== 2) throw new Error(`line ${n + 1}: replay <kind>`);
        st.mode = f[1]!;
        break;
      case "restore": {
        const j = /^[+-]?[0-9]+$/.test(f.slice(1).join("")) ? atoi(f.slice(1).join("")) : 0;
        if (f.length !== 2 || j < 1) throw new Error(`line ${n + 1}: restore <j>`);
        st.params.set("j", f[1]!);
        break;
      }
      case "corrupt":
        parseParams(st, f.slice(1), n + 1);
        break;
      case "backup":
        if (
          (f.length !== 2 && f.length !== 3) ||
          (f[1] !== "page_identical" && f[1] !== "compacted")
        ) {
          throw new Error(`line ${n + 1}: backup page_identical|compacted [p<N>]`);
        }
        st.mode = f[1]!;
        st.pid = f.length === 3 ? parsePid(f[2]!, n + 1) : -1; // no p<N>: the lowest running process
        break;
      case "check":
      case "reopen":
      case "tick":
        break;
      default:
        throw new Error(`line ${n + 1}: unknown step ${JSON.stringify(st.kind)}`);
    }
    tr.steps.push(st);
  }
  if (tr.header.get("format") !== "simulation") {
    throw new Error("missing `# format: simulation` header");
  }
  return tr;
}

function parseParams(st: SimStep, kvs: string[], line: number): void {
  for (const kv of kvs) {
    const eq = kv.indexOf("=");
    if (eq < 0) throw new Error(`line ${line}: bad parameter ${JSON.stringify(kv)}`);
    st.params.set(kv.slice(0, eq), kv.slice(eq + 1));
  }
}

// parsePid parses a process name, p<N>.
function parsePid(name: string, line: number): number {
  if (!/^p[+-]?[0-9]+$/.test(name))
    throw new Error(`line ${line}: bad process "${name}" (want p<N>)`);
  const pid = atoi(name.slice(1));
  if (pid < 0) throw new Error(`line ${line}: bad process "${name}" (want p<N>)`);
  return pid;
}

function intParam(st: SimStep, key: string): number {
  return atoi(st.params.get(key));
}

// faultOf builds the fault a `fault` step arms (simulation-testing.md §6.3).
function faultOf(st: SimStep): SimFault {
  const f: SimFault = { kind: "power_loss", survive: 0, tear: 0, issue: 0, p: 0, nth: 0 };
  switch (st.mode) {
    case "power_loss":
      return {
        ...f,
        survive: intParam(st, "survive"),
        tear: intParam(st, "tear"),
        nth: intParam(st, "nth"),
      };
    case "process_crash":
      return {
        ...f,
        kind: "process_crash",
        issue: intParam(st, "issue"),
        nth: intParam(st, "nth"),
      };
    case "io_error":
      if (st.params.get("op") === "write") return { ...f, kind: "io_write", p: intParam(st, "p") };
      if (st.params.get("op") === "sync")
        return { ...f, kind: "io_sync", nth: intParam(st, "nth") };
      break;
    case "read_error":
      return { ...f, kind: "read_error", p: intParam(st, "p") };
    case "enospc":
      return { ...f, kind: "enospc" };
    case "spill_error":
      return { ...f, kind: "spill_error", p: intParam(st, "p") };
    case "disconnect":
      return { ...f, kind: "disconnect", nth: intParam(st, "nth") };
  }
  const params = [...st.params].map(([k, v]) => `${k}:${v}`).join(" ");
  throw new CheckError(`line ${st.line}: unsupported fault ${st.mode} map[${params}]`);
}

// --- the run ------------------------------------------------------------------------------------

export type SimResult = {
  name: string;
  steps: number;
  violation: string;
  violationStep: number;
  transcriptHash: string;
  opsHash: string;
};

export function resultJson(r: SimResult): string {
  const status = r.violation !== "" ? "fail" : "pass";
  return (
    `{"trace":${JSON.stringify(r.name)},"core":"ts","status":"${status}","steps":${r.steps},` +
    `"violation":${JSON.stringify(r.violation)},"violation_step":${r.violationStep},` +
    `"transcript_hash":"${r.transcriptHash}","ops_hash":"${r.opsHash}"}`
  );
}

// runTrace runs one trace twice — the second run is the self-determinism check (§8.5) — and writes
// the first run's transcript (and, on a violation, the crash image) under out.
export function runTrace(name: string, text: string, out: string, writeImages: boolean): SimResult {
  const res: SimResult = {
    name,
    steps: 0,
    violation: "",
    violationStep: -1,
    transcriptHash: "0000000000000000",
    opsHash: "0000000000000000",
  };
  let tr: SimTrace;
  try {
    tr = parseTrace(text);
  } catch (e) {
    res.violation = "parse trace: " + (e instanceof Error ? e.message : String(e));
    return res;
  }
  const first = new SimRunner(tr);
  if (writeImages) first.imagePrefix = join(out, name + ".ts");
  first.run();
  const transcript = first.transcript.join("");
  res.steps = tr.steps.length;
  res.transcriptHash = fnvStringHex(transcript);
  res.opsHash = first.fs.opsHex();
  writeFileSync(join(out, name + ".ts.jsonl"), transcript);
  if (first.violation !== "") {
    res.violation = first.violation;
    res.violationStep = first.violationStep;
    for (const [file, body] of first.diagnostics)
      writeFileSync(join(out, `${name}.ts.${file}`), body);
    if (first.stack !== "") writeFileSync(join(out, name + ".ts.stack.txt"), first.stack);
    if (first.crashImage !== null)
      writeFileSync(join(out, name + ".ts.crash.img"), first.crashImage);
    return res;
  }
  const second = new SimRunner(tr);
  second.run();
  const transcript2 = second.transcript.join("");
  if (second.violation !== "") {
    res.violation = "nondeterministic: the second run failed: " + second.violation;
    res.violationStep = second.violationStep;
  } else if (transcript2 !== transcript) {
    res.violation =
      "nondeterministic: transcripts differ between two runs" + firstDiff(transcript, transcript2);
  } else if (second.fs.opsHex() !== first.fs.opsHex()) {
    res.violation = "nondeterministic: storage operation logs differ between two runs";
  }
  return res;
}

function firstDiff(a: string, b: string): string {
  const al = a.split("\n");
  const bl = b.split("\n");
  for (let i = 0; i < al.length && i < bl.length; i++) {
    if (al[i] !== bl[i]) return ` (first difference:\n  ${al[i]}\n  ${bl[i]})`;
  }
  return "";
}

function isEngineError(e: unknown): e is EngineError {
  return e instanceof EngineError;
}

// errCode is simCode: an engine error's SQLSTATE, or a "non-engine error" marker the caller turns
// into a violation.
function errCode(e: unknown): string {
  // A checker's error wraps the engine error behind it (Go's simCode reads through %w).
  for (let c: unknown = e; c instanceof Error; c = c.cause) if (isEngineError(c)) return c.code();
  return "non-engine error: " + (e instanceof Error ? e.message : String(e));
}

function errText(e: unknown): string {
  return e instanceof Error ? e.message : String(e);
}

type SimSession = {
  s: Session;
  // The session's own entropy stream (simulation-testing.md §7: lane 8 of the decision function),
  // made the environment's active stream while one of this session's steps runs.
  random: SeededRandom;
  write: boolean;
  pins: Map<string, bigint>; // the version of each database a read session pinned (§8.1: what it must keep seeing)
  pid: number; // the process the session lives in
};

// SimProc is one simulated process: a Database over the shared simulated filesystem, and in a service
// trace its own lock host (S8).
// env is the Environment it opened with (newEnv).
type SimProc = { pid: number; db: Database; host: SimLockHost | null; env: Environment };

// SIM_SERVICE_GRACE_MS is a simulated owner's shutdown grace: its clients' pinned readers live in other
// processes, which no single step can end, so a closing owner always waits out the grace.
const SIM_SERVICE_GRACE_MS = 1000;
// SIM_FILE_LOCK_TIMEOUT_MS is every simulated process's open timeout (the engine default).
const SIM_FILE_LOCK_TIMEOUT_MS = 5000;

// SimGrowth is what a commit left behind, for the next commit's bounded-growth check.
type SimGrowth = {
  reclaimed: boolean; // a quiet commit that must have reclaimed: its free list holds every dead page
  high: number; // its page high-water
  free: number; // its free-list length
};

// SimDB is one database's oracle state (simulation-testing.md §8.1–8.3): main, or a file attachment
// (S4), each with its own versions, history, and durability floor.
class SimDB {
  readonly name: string;
  readonly file: string; // its file in the simulated filesystem
  history = new Map<bigint, Set<string>>(); // version → digests of every generation attempted at it
  version = 0n; // the published version
  lastDigest = ""; // its digest
  floor = 0n; // recovery may never return an older version; 0: the file may vanish
  maxAttempted = 0n; // ... nor a newer one than was ever attempted

  // Bounded growth (§8.3), tracked over one process lifetime: an upper bound on the live count the
  // engine's reclamation trigger compares against, and what the previous commit left.
  high = 0; // the page high-water now
  free = 0; // the free list the next commit allocates from
  trail = 0; // where that free list's trailing run below high starts (high: none)
  lacBound = 0; // ≥ the engine's live-at-last-reclamation
  last: SimGrowth = { reclaimed: false, high: 0, free: 0 }; // the previous commit in this lifetime
  // batchOpen is whether the current step began with a relaxed batch pending on this database's file:
  // its commit keeps the batch's pages off the free list and reuses only the floor's free pages
  // (validated-cow.md §4), so the bounded-growth assertions do not apply to it.
  batchOpen = false;
  // batchPending is whether the step began with a non-empty pending set: a commit then plans inside a
  // batch and may not lower the high-water (validated-cow.md §4). Unlike batchOpen it is false after a
  // recovery whose adopted generation awaits stabilization, which the commit's own first barrier makes
  // the floor.
  batchPending = false;
  // deadline is the simulated-clock deadline of the batch pending on this database's file
  // (validated-cow.md §4.1): the clock of the step that started it plus the trace's flush interval.
  deadline = 0n;
  // due is whether the step began with that batch past its deadline: a commit of this database in the
  // step must flush it first.
  due = false;
  // shrinkDue is set when a relaxed commit lowered the high-water: the next flush (the batch cap, close)
  // must shorten the file (format.md *Trailing truncation*).
  shrinkDue = false;
  // ownerLost is set when an owner died: until a process observes the database again, it may have
  // recovered any version from the floor up.
  ownerLost = false;

  // Encryption at rest (S12–S13): the simulation key the database is encrypted under (SIM_KEYS), or -1
  // when it is plaintext; and keyChange, a credential change or rekey of this step, which recovery
  // after it checks the file against.
  key = -1;
  keyChange: SimKeyChange | null = null;

  constructor(name: string, file: string) {
    this.name = name;
    this.file = file;
  }

  addHistory(v: bigint, digest: string): void {
    let set = this.history.get(v);
    if (set === undefined) {
      set = new Set();
      this.history.set(v, set);
    }
    set.add(digest);
  }

  inHistory(v: bigint, digest: string): boolean {
    return this.history.get(v)?.has(digest) ?? false;
  }
}

// SimKeyChange is a key step in progress: the key before it and the one it installs. When the file's
// directory entry was not durable as it began (an earlier compaction's or rekey's rename awaits the
// next opener's directory barrier), a power loss may bring an older file back under an older key.
type SimKeyChange = { old: number; next: number; entryPending: boolean };

// SimBackup is a successful backup of main (S13): its file, the version and contents a new process
// opens there, and the key main had when it was taken.
type SimBackup = { n: number; file: string; version: bigint; digest: string; key: number };

// The internals of a Database the runner reads: the published roots and each domain's storage owner.
type CoreView = {
  committed: { txid: bigint };
  service: object | null;
  client: PageClient | null;
  attached: Map<string, { txid: bigint }>;
  storage: Engine;
  // svc is set on a file attachment under the page service: its inner handle's core (README.md §6.6).
  attachments: Map<string, { storage: Engine; svc: { core: CoreView } | null }>;
  attachedRoot(name: string): { txid: bigint } | undefined;
};

// serviceCoreOf is the core whose page-service role serves database d in db: the handle's own for
// main, an attachment's inner handle's (README.md §6.6), or null when d is not attached under the
// service.
function serviceCoreOf(db: Database, d: SimDB): CoreView | null {
  const core = coreOf(db);
  if (d.name === "main") return core;
  return core.attachments.get(d.name)?.svc?.core ?? null;
}

// attachedVersionOf is the version of attachment d that db has adopted (0 when not attached): an
// attachment under the page service reports its inner handle's.
function attachedVersionOf(db: Database, d: SimDB): bigint {
  const core = coreOf(db);
  if (!core.attachments.has(d.name)) return 0n;
  return core.attachedRoot(d.name)?.txid ?? 0n;
}

// sessionVersionOf is the version of attachment name a session reads (its pinned or base root), or 0.
function sessionVersionOf(s: Session, name: string): bigint {
  const engine = (s as unknown as { engine: { attachedCommitted: Map<string, { txid: bigint }> } })
    .engine;
  return engine.attachedCommitted.get(name)?.txid ?? 0n;
}

function coreOf(db: Database): CoreView {
  return (db as unknown as { core: CoreView }).core;
}

// versionOf is the version db has published, without refreshing from another process (Go's
// Database.Version; the TS getter also adopts a newer shared generation).
function versionOf(db: Database): bigint {
  return coreOf(db).committed.txid;
}

const DIGEST_RELATIONS = [
  "jed_tables",
  "jed_columns",
  "jed_indexes",
  "jed_constraints",
  "jed_sequences",
];

// qualifier is the prefix that names database d's relations: none for main, `name.` for an
// attachment.
function qualifier(d: SimDB): string {
  return d.name === "main" ? "" : d.name + ".";
}

// emptyDigest is the digest of a freshly created database (an attachment's version 1): every catalog
// relation empty and no table.
function emptyDigest(d: SimDB): string {
  let b = "";
  for (const rel of DIGEST_RELATIONS) b += "SELECT * FROM " + qualifier(d) + rel + "\n\n\n";
  return fnvStringHex(b);
}

// dbsJSON renders the attachments' check/recovery state as `,"dbs":{"a1":{...},...}`, or "" with
// none.
function dbsJSON(entries: string[]): string {
  return entries.length === 0 ? "" : `,"dbs":{` + entries.join(",") + "}";
}

// metaOf reads the page high-water and live page count of the meta slot holding version v.
function metaOf(
  image: Uint8Array | null,
  ps: number,
  v: bigint,
): { pageCount: number; live: number } | null {
  if (image === null) return null;
  for (let slot = 0; slot < 2; slot++) {
    const off = slot * ps;
    if (off + ps > image.length) continue;
    const m = parseCommitMeta(image.subarray(off, off + ps), ps, 0xffff_ffff);
    if (m !== null && m.txid === v) return { pageCount: m.pageCount, live: m.livePages };
  }
  return null;
}

// SimRandom is the runner's environment random source: it draws from the stream of the session whose
// step is running (each session keeps its own SeededRandom, as simulation-testing.md §7 specifies),
// and from OS entropy outside any session — where nothing reads it.
class SimRandom implements RandomSource {
  active: SeededRandom | null = null;

  fill(buf: Uint8Array): void {
    if (this.active !== null) this.active.fill(buf);
    else osRandomSource().fill(buf);
  }
}

// SIM_KEYS are the simulation's host keys (S12): key n is 32 bytes of 0x4A + n, so key 0 is the
// goldens' (spec/fileformat/verify.rb tries all four on an encrypted image).
const SIM_KEYS: Credential[] = [0, 1, 2, 3].map((n) => ({
  key: new Uint8Array(32).fill(0x4a + n),
}));

// simCredential is simulation key k's credential, or none for -1, plaintext.
function simCredential(k: number): Credential | undefined {
  return k < 0 ? undefined : SIM_KEYS[k];
}

// targetKey parses a key step's target: simulation key 1–3, or -1 for `plain`.
function targetKey(s: string): number {
  return s === "plain" ? -1 : atoi(s);
}

export class SimRunner {
  private tr: SimTrace;
  private seed: bigint;
  private pageSize: number;
  private cacheBytes: number;
  private clock: bigint;
  // The Environment every process opens its databases with (spec/design/environment.md): the
  // per-session random streams and the trace clock, which starts at the `clock` header and advances
  // only on `clock` steps.
  private random = new SimRandom();
  private clockSource: ClockSource;

  // Handle settings from the header (simulation-testing.md §5, slice S3), applied at every open.
  private workMem: number; // a session's work_mem
  private tempBuffers: number; // a session's temp_buffers: past it, a temp domain spills (temp-tables.md §6)
  private maxQueryMemory: bigint; // a trace session's max_query_memory_bytes (oracle reads: unlimited)
  private maxStorageBytes: bigint; // the database's max_storage_bytes
  // relaxed is the header's synchronous = off (validated-cow.md §4): every process batches its
  // barriers, flushing inline (TypeScript always does) so the barrier lands in the step that reached
  // the batch cap.
  private relaxed: boolean;
  // flushIntervalMs is the header's flush_interval_ms (validated-cow.md §4.1; absent: 0, no time-based
  // flush), measured on the simulated clock with no idle flusher.
  private flushIntervalMs: number;

  fs: SimFS;
  private db: Database | null = null; // the database of the process running the current step
  private sessions = new Map<string, SimSession>();

  // Processes (simulation-testing.md §14 S8). A single-process trace has only p0, opened without
  // coordination; a `# processes: service` trace opens every process under the page service, over the
  // simulated lock host and network: the first is the owner, later ones its clients.
  private service: boolean;
  private net = new SimNet();
  private procs = new Map<number, SimProc>();
  private cur = 0; // the process running the current step
  private locks: SimLockTable | null = null;
  private armed: SimFault | null = null;

  transcript: string[] = [];

  // Oracle state (simulation-testing.md §8.1–8.3), one per database: main first, then each file
  // attachment (S4) in name order.
  private dbs = new Map<string, SimDB>();

  violation = "";
  violationStep = -1;
  crashImage: Uint8Array | null = null;
  stack = ""; // the stack of an unexpected throw (Go: a panic)

  private lastDigestText = ""; // the text the most recent digest folded
  private digestErr: unknown = null; // why the most recent digest failed
  diagnostics = new Map<string, string>(); // artifact name → contents, written on a violation
  imagePrefix = ""; // when set, each recovery's image is written to <prefix>.step<N>[.<db>].img
  private backups = 0; // backup steps run, naming each destination

  // Encryption at rest (slices S12–S13, spec/fileformat/encrypted.md): an encrypted trace creates main
  // and every attachment encrypted, seals every process's scratch files, and gives each process opening
  // its own seeded key-entropy stream (newEnv). Each database's key is its SimDB's.
  private encrypted: boolean;
  private opens = 0n; // Environments built so far, each a process opening (newEnv)
  // backupsOK are main's successful backups in order, the ones a restore may copy back (S13).
  private backupsOK: SimBackup[] = [];
  private stepIndex = 0; // the step running, for reopenStale's transcript line

  constructor(tr: SimTrace) {
    this.tr = tr;
    this.seed = parseUint64(tr.header.get("seed"));
    let ps = atoi(tr.header.get("page_size"));
    if (ps === 0) ps = 256;
    this.pageSize = ps;
    this.cacheBytes = atoi(tr.header.get("cache_bytes"));
    this.clock = parseInt64(tr.header.get("clock"));
    this.clockSource = { nowMicros: () => this.clock };
    this.encrypted = tr.header.get("encrypted") === "1";
    this.workMem = atoi(tr.header.get("work_mem"));
    this.tempBuffers = atoi(tr.header.get("temp_buffers"));
    this.maxQueryMemory = parseInt64(tr.header.get("max_query_memory_bytes"));
    this.maxStorageBytes = parseInt64(tr.header.get("max_storage_bytes"));
    this.relaxed = tr.header.get("synchronous") === "off";
    this.flushIntervalMs = atoi(tr.header.get("flush_interval_ms"));
    let sector = atoi(tr.header.get("sector"));
    if (sector <= 0) sector = SECTOR_DEFAULT;
    this.fs = new SimFS(this.seed, sector, ps);
    this.fs.archiving = this.encrypted;
    this.service = tr.header.get("processes") === "service";
  }

  // credential is database d's credential: its simulation key's, or none while it is plaintext.
  private credential(d: SimDB): Credential | undefined {
    return simCredential(d.key);
  }

  // newEnv is the Environment of one opening of process pid (or of a create the runner does as a host
  // would): the shared seeded SQL source and clock, and in an encrypted trace an insecure key-entropy
  // stream of its own, seeded from lane 14 (§5) by the run's count of openings and pid. The seeded
  // source starts every database's stream afresh from its seed, so a stream shared by two openings —
  // an owner and its client, or one process before and after a crash — would draw the same data keys
  // and nonces, which the CSPRNG it models never does (encryption.md §3).
  private newEnv(pid: number): Environment {
    let env = Environment.builder().randomSource(this.random).clockSource(this.clockSource);
    if (this.encrypted) {
      // Seeded so the cores' images stay byte-identical (encrypted.md §8).
      env = env.insecureSeededKeyEntropy(
        decide(this.seed, LANE_KEY_SEED, this.opens, BigInt(pid), 0n),
      );
    }
    this.opens++;
    return env.build();
  }

  // procEnv is the Environment the step's process opened with.
  private procEnv(): Environment {
    return this.procs.get(this.cur)!.env;
  }

  // createKey is the key a database is created under: simulation key 0 in an encrypted trace, else
  // none.
  private createKey(): number {
    return this.encrypted ? 0 : -1;
  }

  // unlocks reports whether simulation key k (-1: none) opens image: k unwraps its key block, or the
  // file is plaintext and k is -1.
  private unlocks(image: Uint8Array | null, k: number): boolean {
    const ps = this.pageSize;
    if (image === null || image.length < 2 * ps) return false;
    let suite: number;
    try {
      suite = fileSuite(image.subarray(0, ps), image.subarray(ps, 2 * ps)) ?? 0;
    } catch {
      return false;
    }
    if (k < 0 || suite === 0) return k < 0 && suite === 0;
    if (image.length < 4 * ps) return false;
    try {
      unlockCodec(
        image.subarray(2 * ps, 3 * ps),
        image.subarray(3 * ps, 4 * ps),
        SIM_KEYS[k]!,
        osKeyEntropy(),
      );
      return true;
    } catch {
      return false;
    }
  }

  // unlocked records the key recovery opened database d with.
  private unlocked(i: number, d: SimDB): void {
    const dbField = d.name !== "main" ? `,"db":${goQuote(d.name)}` : "";
    this.emit(`{"i":${i},"op":"unlocked"${dbField},"key":${d.key}}`);
  }

  // settleKey runs after a crash that interrupted a credential change or rekey of d (S12): exactly one
  // of the old and new keys (-1: plaintext, a conversion) opens d's file, and the new one when the step
  // had succeeded (its last barrier ran). The runner continues with whichever opens.
  private settleKey(i: number, d: SimDB, image: Uint8Array | null): boolean {
    const change = d.keyChange;
    d.keyChange = null;
    if (change === null) return this.followKey(i, d, image);
    const { old, next } = change;
    const acknowledged = d.key === next;
    const a = this.unlocks(image, old);
    const b = this.unlocks(image, next);
    if (old === next && b) {
      // A change to the key already in use (a rotation): it still opens.
    } else if (old !== next && a && !b && !acknowledged) d.key = old;
    else if (old !== next && !a && b) d.key = next;
    else if (change.entryPending && !a && !b) {
      // An older file came back (its rename was never made durable): whichever key opens it.
      return this.followKey(i, d, image);
    } else if (old === next) {
      this.fail(i, `encryption: key ${next} no longer opens ${d.name}`);
      return false;
    } else if (a && !b) {
      this.fail(i, `durability: the acknowledged change of ${d.name} to key ${next} was lost`);
      return false;
    } else {
      this.fail(
        i,
        `encryption: key ${old} opens ${d.name}: ${a}, key ${next}: ${b}; want exactly one`,
      );
      return false;
    }
    this.unlocked(i, d);
    return true;
  }

  // followKey is recovery outside a key step: a rekey whose rename was not yet durable in its directory
  // may come back as the older file under its older key (validated-cow.md §3), or plaintext, so d opens
  // with whichever simulation key opens the recovered file, the current one first.
  private followKey(i: number, d: SimDB, image: Uint8Array | null): boolean {
    if (!this.encrypted || image === null) return true;
    const order = [d.key, ...[-1, 0, 1, 2, 3].filter((k) => k !== d.key)];
    for (const k of order) {
      if (this.unlocks(image, k)) {
        if (k !== d.key) {
          d.key = k;
          this.unlocked(i, d);
        }
        return true;
      }
    }
    this.fail(i, `encryption: no simulation key opens ${d.name}`);
    return false;
  }

  // clearKeyChanges forgets every database's key step once its step is over.
  private clearKeyChanges(): void {
    for (const d of this.dbs.values()) d.keyChange = null;
  }

  private fail(step: number, msg: string): void {
    if (this.violation === "") {
      const where = step >= 0 ? `step ${step} (line ${this.tr.steps[step]!.line}): ` : "setup: ";
      this.violation = where + msg;
      this.violationStep = step;
    }
  }

  private emit(line: string): void {
    this.transcript.push(line + "\n");
  }

  private get database(): Database {
    return this.db!;
  }

  // main is the main database's oracle state.
  private main(): SimDB {
    return this.dbs.get("main")!;
  }

  // attachedNames lists the attachments the runner tracks, in name order.
  private attachedNames(): string[] {
    return [...this.dbs.keys()].filter((n) => n !== "main").sort(compareUtf8);
  }

  // order lists every tracked database: main, then the attachments in name order.
  private order(): SimDB[] {
    return [this.main(), ...this.attachedNames().map((n) => this.dbs.get(n)!)];
  }

  // open opens a Database over the simulated disk through the ordinary demand-paged loader — the path
  // a reopening process takes, including validated-COW recovery (validated-cow.md §1) — and
  // re-attaches every tracked attachment whose file exists.
  private open(): void {
    this.openProc(0);
    if (this.service) return; // openProc re-attached them
    for (const name of this.attachedNames()) {
      const d = this.dbs.get(name)!;
      if (!this.fs.files.has(d.file)) continue; // the caller decides whether losing it was allowed
      try {
        this.attach(name);
      } catch (e) {
        if (e instanceof EngineError) e.message = `re-attach ${name}: ${e.message}`;
        throw e;
      }
    }
  }

  // attach attaches the existing file of attachment name read-write to the current process: under the
  // page service in a service trace (owner or page client of the file, README.md §6.6), uncoordinated
  // otherwise.
  private attach(name: string): void {
    const locking = this.service ? "auto" : "none";
    const d = this.dbs.get(name)!;
    this.database.attach(
      name,
      attachFile(d.file, { locking, credential: this.credential(d) }),
      false,
    );
  }

  // openProc starts process pid. A service trace elects it through the simulated lock host and
  // network, exactly as openDatabase does through the OS host.
  private openProc(pid: number): void {
    let host: SimLockHost | null = null;
    let db: Database;
    const env = this.newEnv(pid);
    if (this.service) {
      if (this.locks === null) {
        this.locks = new SimLockTable({
          get: () => this.clock,
          advance: (micros) => {
            this.clock += micros;
          },
        });
      }
      host = new SimLockHost(this.locks, pid, this.net);
      db = this.openServiceProc(pid, host, env);
    } else db = this.openDatabase(env);
    this.procs.set(pid, { pid, db, host, env });
    this.cur = pid;
    this.db = db;
    if (this.service) {
      // Every process attaches every tracked attachment whose file exists: the owner of the file, or a
      // page client of whichever process owns it.
      for (const name of this.attachedNames()) {
        if (!this.fs.files.has(this.dbs.get(name)!.file)) continue;
        try {
          this.attach(name);
        } catch (e) {
          try {
            this.closeProc(pid);
          } catch {
            // The re-attach failure is the one reported.
          }
          if (e instanceof EngineError) e.message = `re-attach ${name}: ${e.message}`;
          throw e;
        }
      }
      this.net.pump();
    }
  }

  // openServiceProc opens process pid under the page service (S8): its own lock host over the shared
  // lock table and network, the simulated filesystem and spill sink, and no background re-election, so
  // a client re-elects at its next transaction begin, in trace order. Every owner limit that would
  // start a timer is off.
  private openServiceProc(pid: number, host: SimLockHost, env: Environment): Database {
    const handoff = new ServiceHandoff(
      MAIN_FILE,
      {
        idleInTransactionTimeoutMs: 0,
        idleSessionTimeoutMs: 0,
        shutdownGraceMs: SIM_SERVICE_GRACE_MS,
        // The handle's setting, which its file attachments follow whatever role it holds.
        synchronous: this.relaxed ? "off" : "on",
        flushIntervalMs: this.flushIntervalMs,
        // Every process seals its scratch files, so encrypting a plaintext database is allowed (S13).
        scratchEncryption: this.encrypted ? "on" : "auto",
      },
      false,
      SIM_FILE_LOCK_TIMEOUT_MS,
      {
        cacheBytes: this.cacheBytes > 0 ? this.cacheBytes : undefined,
        credential: this.credential(this.main()),
        scratchEncryption: this.encrypted ? "on" : "auto",
      },
      env,
      // A promoting client opens the file with the data key it holds (encrypted.md §14).
      (held) => this.openEngine(this.fs.openStore(MAIN_FILE, false, false), env, held),
      {
        lock: host,
        files: this.fs,
        adoptClient: (e) => {
          e.fileHost = this.fs;
          e.spillSink = this.fs.spillSink();
        },
        background: false,
      },
    );
    let db: Database;
    try {
      db = openServiceWith(handoff);
    } catch (e) {
      this.locks!.release(pid);
      this.net.kill(pid);
      throw e;
    }
    if (this.maxStorageBytes > 0n) db.setMaxStorageBytes("main", this.maxStorageBytes);
    return db;
  }

  // ownerPid is the running process that owns the main database under the page service, or -1.
  private ownerPid(): number {
    return this.ownerPidOf(this.main());
  }

  // ownerPidOf is the running process that owns database d under the page service, or -1.
  private ownerPidOf(d: SimDB): number {
    for (const pid of this.livePids()) {
      const c = serviceCoreOf(this.procs.get(pid)!.db, d);
      if (c !== null && c.service !== null) return pid;
    }
    return -1;
  }

  // ownerPids lists the running processes that own main or an attachment under the page service.
  private ownerPids(): number[] {
    const pids: number[] = [];
    for (const pid of this.livePids()) {
      const db = this.procs.get(pid)!.db;
      for (const d of this.order()) {
        const c = serviceCoreOf(db, d);
        if (c !== null && c.service !== null) {
          pids.push(pid);
          break;
        }
      }
    }
    return pids;
  }

  private openDatabase(env: Environment): Database {
    const main = this.fs.main();
    if (main === undefined) throw engineError("io_error", "the database file is gone");
    const db = Database.fromEngine(this.openEngine(main, env, null), null);
    if (this.maxStorageBytes > 0n) db.setMaxStorageBytes("main", this.maxStorageBytes);
    return db;
  }

  // openEngine opens the main database's engine over store through the ordinary demand-paged loader,
  // with the simulated filesystem as its file host and spill sink.
  // held is the data key a promoting page client holds (encrypted.md §14): it opens the file in place
  // of the credential, and a differing key-block pair is left unrepaired.
  private openEngine(store: BlockStore, env: Environment, held: PageCodec | null): Engine {
    const pager = Pager.fromStore(store);
    const cache = this.cacheBytes > 0 ? this.cacheBytes : DEFAULT_CACHE_BYTES;
    let codec: PageCodec | null;
    if (held !== null) {
      runSync(adoptHeldCodecSteps(pager, held));
      codec = held;
    } else codec = runSync(unlockPagerSteps(pager, this.credential(this.main()), env));
    let e: Engine;
    try {
      e = loadEnginePaged(new SharedPaging(pager, cacheLeaves(cache, pager.pageSize), codec), env);
    } catch (err) {
      // A meta the held key cannot authenticate: the owner rekeyed the file before it left (28P04,
      // spec/fileformat/encrypted.md §14), as openVia reports it.
      if (
        held !== null &&
        isEngineError(err) &&
        err.code() === "XX001" &&
        runSync(heldKeyStaleSteps(pager, held))
      ) {
        throw engineError(
          "stale_key",
          "the database was rekeyed since this handle opened it; reopen it",
        );
      }
      throw err;
    }
    e.path = MAIN_FILE; // marks the engine durable; the simulated filesystem is its only storage
    // A writable open finishes a credential change a crash interrupted (encrypted.md §5).
    if (held === null) runSync(repairKeyBlockSteps(e));
    // Create, compaction, and attachments go through the simulated filesystem.
    e.fileHost = this.fs;
    e.persistHook = persistImpl;
    // Every flush lands in the step that caused it: no idle flusher.
    setDurability(e, {
      relaxed: this.relaxed,
      flushIntervalMs: this.flushIntervalMs,
      idleFlush: false,
    });
    // Spill and temp-table spill scratch files, whose operations can fail; sealed in an encrypted trace
    // (encrypted.md §11), whatever main is now, so encrypting a plaintext database is allowed (S13).
    e.spillSink = sealScratch(this.fs.spillSink(), this.encrypted, env);
    return e;
  }

  run(): void {
    const processes = this.tr.header.get("processes");
    if (processes !== undefined && processes !== "" && processes !== "service") {
      this.violation = `unsupported processes mode ${processes}`;
      return;
    }
    // Create the database through the simulated filesystem, as the host's create does: a temp file,
    // its sync, the rename, and the directory barrier (S4).
    const m = new SimDB("main", MAIN_FILE);
    m.key = this.createKey();
    try {
      closeEngine(
        createVia(this.fs, MAIN_FILE, {
          pageSize: this.pageSize,
          credential: this.credential(m),
          environment: this.newEnv(0),
        }),
      );
    } catch (e) {
      this.violation = "create: " + errText(e);
      return;
    }
    this.dbs.set("main", m);
    try {
      this.open();
    } catch (e) {
      this.violation = "initial open: " + errText(e);
      return;
    }
    m.version = versionOf(this.database);
    m.floor = m.version;
    m.maxAttempted = m.version;
    const d = this.committedDigest(m);
    if (d === null) {
      this.violation = "initial digest failed";
      return;
    }
    m.lastDigest = d;
    m.addHistory(m.version, d);
    this.observeGrowth(m);
    for (let i = 0; i < this.tr.steps.length; i++) {
      if (!this.step(i) || this.violation !== "") return;
    }
  }

  // image copies a database file's cache — what a new process would open — or null if it is gone.
  private image(d: SimDB): Uint8Array | null {
    return this.fs.files.get(d.file)?.cache.slice() ?? null;
  }

  // step runs one trace step; false stops the run. An unexpected throw anywhere is a violation.
  private step(i: number): boolean {
    try {
      return this.stepInner(i);
    } catch (e) {
      this.fail(i, "panic: " + errText(e));
      this.stack = e instanceof Error ? (e.stack ?? "") : String(e);
      return false;
    }
  }

  private stepInner(i: number): boolean {
    const st = this.tr.steps[i]!;
    this.stepIndex = i;
    switch (st.kind) {
      case "fault": {
        let f: SimFault;
        try {
          f = faultOf(st);
        } catch (e) {
          this.fail(i, errText(e));
          return false;
        }
        this.armed = f;
        this.emit(`{"i":${i},"op":"fault","kind":${goQuote(st.mode)}}`);
        return true;
      }
      case "crash":
        this.fs.beginStep(i, null);
        if (st.mode === "power") {
          this.fs.powerLoss(i, intParam(st, "survive"), intParam(st, "tear"));
        }
        return this.recover(i, "none");
      case "clock":
        this.clock += parseInt64(st.params.get("delta"));
        this.emit(`{"i":${i},"op":"clock"}`);
        return true;
      case "tick":
        this.emit(`{"i":${i},"op":"tick"}`);
        return true;
      case "disconnect": {
        // The process's connection to the owner ends (S8): both ends see end of stream.
        const p = this.procs.get(st.pid);
        const client = p !== undefined ? coreOf(p.db).client : null;
        if (client === null) {
          this.emit(`{"i":${i},"op":"disconnect","pid":${st.pid},"skip":true}`);
          return true;
        }
        client.disconnect();
        this.net.pump();
        this.emit(`{"i":${i},"op":"disconnect","pid":${st.pid}}`);
        return true;
      }
      case "exit": {
        if (!this.procs.has(st.pid)) {
          this.emit(`{"i":${i},"op":"exit","pid":${st.pid},"skip":true}`);
          return true;
        }
        try {
          this.closeProc(st.pid);
        } catch (e) {
          if (!isEngineError(e)) throw e;
          this.fail(i, `exit p${st.pid}: ${errText(e)}`);
          return false;
        }
        this.emit(`{"i":${i},"op":"exit","pid":${st.pid}}`);
        return true;
      }
      case "kill":
        if (!this.procs.has(st.pid)) {
          this.emit(`{"i":${i},"op":"kill","pid":${st.pid},"skip":true}`);
          return true;
        }
        this.dropProc(st.pid);
        if (this.procs.size === 0) {
          this.fs.beginStep(i, null);
          return this.recover(i, "none");
        }
        this.emit(`{"i":${i},"op":"kill","pid":${st.pid}}`);
        return true;
      case "corrupt":
        this.fs.beginStep(i, null);
        return this.stepCorrupt(i, st);
      case "replay":
        this.fs.beginStep(i, null);
        return this.stepReplay(i, st.mode);
      case "restore":
        this.fs.beginStep(i, null);
        return this.stepRestore(i, intParam(st, "j"));
    }

    // A step that needs a process when none is running (the last one exited) restarts p0 first.
    if (this.procs.size === 0 && st.kind !== "spawn") {
      this.fs.beginStep(i, null);
      this.stepSpawn(i, 0);
      if (this.violation !== "" || this.procs.size === 0) {
        if (this.violation === "") this.fail(i, "p0 could not restart");
        return false;
      }
    }
    const armed = this.armed;
    this.armed = null;
    const start = new Map<string, bigint>();
    const now = this.clock;
    const timed = this.flushIntervalMs > 0;
    for (const [name, d] of this.dbs) {
      start.set(name, d.version);
      const open = this.relaxed && !this.engineFlushed(d);
      const pending = this.relaxed && this.enginePending(d);
      // A batch past its deadline is flushed by the step's commit before it plans (validated-cow.md
      // §4.1), so that commit plans with nothing pending.
      const due = pending && timed && now >= d.deadline;
      d.batchOpen = open && !due;
      d.batchPending = pending && !due;
      d.due = due;
    }
    const pid = this.stepPid(st);
    if (pid !== null && st.kind !== "spawn" && !this.selectProc(pid)) {
      if (st.kind === "open") {
        this.emit(`{"i":${i},"op":"open","sid":${goQuote(st.sid)},"skip":true}`);
        return true;
      }
      if (st.kind === "backup") {
        this.emit(`{"i":${i},"op":"backup","pid":${st.pid},"skip":true}`);
        return true;
      }
      if (this.procs.size === 0) {
        this.fail(i, "no process is running");
        return false;
      }
    }
    const diskFault = armed !== null && armed.kind === "disconnect" ? null : armed;
    this.net.beginStep(armed !== null && armed.kind === "disconnect" ? armed.nth : 0);
    this.fs.beginStep(i, diskFault);
    // Entropy drawn during this step comes from its session's stream (none outside a session step).
    this.random.active = this.sessions.get(st.sid)?.random ?? null;
    switch (st.kind) {
      case "spawn":
        this.stepSpawn(i, st.pid);
        break;
      case "open":
        this.stepOpen(i, st);
        break;
      case "on":
        this.stepOn(i, st);
        break;
      case "commit":
        this.stepCommit(i, st);
        break;
      case "rollback":
      case "close":
        this.stepEnd(i, st);
        break;
      case "check":
        this.stepCheck(i);
        break;
      case "compact":
        this.stepCompact(i, st.sid, false, 0);
        break;
      case "rekey":
        this.stepRekey(i, st.sid, targetKey(st.mode));
        break;
      case "change_key":
        this.stepChangeKey(i, st.sid, targetKey(st.mode));
        break;
      case "backup":
        this.stepBackup(i, st);
        break;
      case "attach":
        this.stepAttach(i, st.sid);
        break;
      case "reopen":
        if (!this.stepReopen(i)) return false;
        break;
    }
    if (this.service) this.net.pump();
    if (this.violation !== "") return false;
    // A completed barrier made every earlier write durable: the generation a database published when
    // the step began can no longer be lost (§8.2).
    for (const [name, d] of this.dbs) {
      const f = this.fs.files.get(d.file);
      if (f === undefined) continue;
      const s0 = start.get(name);
      // Under synchronous = off a barrier proves the step's starting version durable only when the
      // engine was not batching then: a pending version may be durable by accident (a file growth is a
      // full fsync) and still be overwritten by the next commit of its batch (validated-cow.md §4).
      // A commit past its batch's deadline flushes before it plans (validated-cow.md §4.1).
      if (
        d.due &&
        s0 !== undefined &&
        d.version > s0 &&
        !this.fs.dead &&
        this.fs.fired === "" &&
        !f.barrierOK
      ) {
        this.fail(
          i,
          `time-based flush: version ${d.version} of ${name} committed past its batch's deadline without a flush`,
        );
        return false;
      }
      if (f.barrierOK && !d.batchOpen && s0 !== undefined && s0 > d.floor) d.floor = s0;
      if (
        !this.relaxed ||
        this.fs.dead ||
        this.fs.fired !== "" ||
        d.version <= d.floor ||
        !this.engineFlushed(d) ||
        !this.fs.entryDurable(d.file)
      ) {
        continue;
      }
      // The engine holds nothing pending: it treats the published version as flushed, and will
      // overwrite only the other slot. Hold it to that, after checking the claim against the disk.
      // Its directory entry must be durable too: a process that died between compaction's rename and
      // its directory barrier leaves the new file readable, and a power loss before the next opener's
      // first commit syncs the directory brings the older file back (validated-cow.md §3).
      if (f.metaPending()) {
        this.fail(
          i,
          `durability: the engine treats version ${d.version} of ${d.name} as flushed, but no barrier covered its meta`,
        );
        return false;
      }
      d.floor = d.version;
    }
    // Checked against the floor this step leaves (a flush in the step moved it).
    for (const d of this.order()) if (!this.checkTruncated(i, d)) return false;
    // A batch this step started ends at the step's clock plus the interval (validated-cow.md §4.1).
    if (this.relaxed && timed) {
      const interval = BigInt(this.flushIntervalMs) * 1000n;
      const max = (1n << 63n) - 1n;
      for (const d of this.order()) {
        // A batch starts in a step that began with nothing pending, or whose commit flushed a batch
        // past its deadline.
        const started = d.due ? d.version > (start.get(d.name) ?? 0n) : !d.batchPending;
        if (started && this.enginePending(d)) {
          const deadline = now + interval;
          d.deadline = deadline > max ? max : deadline;
        }
      }
    }
    if (armed === null) {
      this.clearKeyChanges();
      return true;
    }
    if (armed.kind === "disconnect") {
      this.clearKeyChanges();
      // A lost connection ends no process: its client re-elects at its next begin.
      const how = this.net.disconnected ? "frame" : "end";
      this.emit(`{"i":${i},"op":"disconnected","fired":${goQuote(how)}}`);
      return true;
    }
    // Every faulted step ends the process; a power loss also discards the unsynced writes (§5).
    const fired = this.fs.fired === "" ? "end" : this.fs.fired;
    if (armed.kind === "power_loss") {
      this.fs.powerLoss(i, armed.survive, armed.tear);
      return this.recover(i, fired);
    }
    // In a service trace any other fault kills the owner, the only process that touches the file,
    // whichever process's step drove its I/O; the others keep running over the same kernel state.
    if (this.service && this.procs.size > 1) {
      // Every owner — of main or of an attachment — is a process that may have touched a file after
      // the fault fired, so each dies; with attachments owned elsewhere that may be more than one.
      let dead = this.ownerPids();
      if (dead.length === 0) dead = [this.cur];
      if (dead.length < this.procs.size) {
        for (const pid of dead) this.dropProc(pid);
        this.fs.processDeath();
        for (const pid of dead) {
          this.emit(`{"i":${i},"op":"killed","pid":${pid},"fired":${goQuote(fired)}}`);
        }
        // The survivors run on: a key step the dead owner interrupted is settled on the kernel's view
        // of each file, which the next opener reads.
        for (const d of this.order()) {
          const image = this.image(d);
          if (d.keyChange !== null && image !== null && !this.settleKey(i, d, image)) return false;
        }
        return true;
      }
    }
    return this.recover(i, fired);
  }

  // dbVersion is the version of database d the current process has published.
  private dbVersion(d: SimDB): bigint {
    if (d.name === "main") return versionOf(this.database);
    return attachedVersionOf(this.database, d);
  }

  // versionsJSON renders the attachments' versions as `,"dbs":{"a1":V,...}`, or "" with none, so a
  // trace without attachments keeps its transcript shape.
  private versionsJSON(versions: Map<string, bigint>): string {
    const names = this.attachedNames();
    if (names.length === 0) return "";
    const parts: string[] = [];
    for (const name of names) {
      const v = versions.get(name);
      if (v !== undefined) parts.push(`${goQuote(name)}:${v}`);
    }
    return `,"dbs":{` + parts.join(",") + "}";
  }

  private stepOpen(i: number, st: SimStep): void {
    if (this.sessions.has(st.sid)) {
      this.fail(i, `session ${st.sid} already open`);
      return;
    }
    if (st.mode === "write") {
      for (const [sid, ss] of this.sessions) {
        if (ss.write) {
          this.fail(i, `open ${st.sid} write while ${sid} holds the writer gate`);
          return;
        }
      }
    } else if (st.mode !== "read") {
      this.fail(i, `unknown session mode ${goQuote(st.mode)}`);
      return;
    }
    let s: Session;
    try {
      s = st.mode === "read" ? this.database.readSession() : this.database.writeSession();
    } catch (e) {
      // The TS session begins at open, where Go's begins at its first read: a stale data key (S13)
      // surfaces here, and the host reopens the process as after Go's first read.
      if (!isEngineError(e)) throw e;
      this.digestErr = e;
      if (!this.staleKeyError()) throw e;
      this.emit(`{"i":${i},"op":"open","sid":${goQuote(st.sid)},"error":${goQuote(e.code())}}`);
      this.reopenStale();
      return;
    }
    const random = new SeededRandom(decide(this.seed, LANE_SESSION, BigInt(i), 0n, 0n));
    if (this.workMem > 0) s.setWorkMem(this.workMem);
    if (this.tempBuffers > 0) s.setTempBuffers(this.tempBuffers);
    if (this.maxQueryMemory > 0n) s.setMaxQueryMemoryBytes(this.maxQueryMemory);
    if (this.service) {
      // A session that finds its process's data key stale fails to open, and the host reopens the
      // process (reopenStale).
      const stale = (dg: string | null): boolean => {
        if (dg !== null || !this.staleKeyError()) return false;
        if (st.mode === "write") {
          try {
            s.rollback();
          } catch (e) {
            if (!isEngineError(e)) throw e;
          }
        } else closeQuietly(s);
        this.emit(
          `{"i":${i},"op":"open","sid":${goQuote(st.sid)},"error":${goQuote(errCode(this.digestErr))}}`,
        );
        this.reopenStale();
        return true;
      };
      const d = this.digest(s, this.main());
      if (stale(d) || !this.observe(i, "session " + st.sid, s.version, d)) return;
      for (const name of this.attachedNames()) {
        const a = this.dbs.get(name)!;
        const v = sessionVersionOf(s, name);
        if (v === 0n) continue;
        const dg = this.digest(s, a);
        if (stale(dg) || !this.observeDB(i, a, "session " + st.sid, v, dg)) return;
      }
    }
    // A session pins every database's committed root when it opens.
    const pins = new Map<string, bigint>([["main", s.version]]);
    for (const name of this.attachedNames()) {
      const v = sessionVersionOf(s, name);
      if (v !== 0n) pins.set(name, v);
    }
    this.sessions.set(st.sid, { s, random, write: st.mode === "write", pins, pid: this.cur });
    this.emit(
      `{"i":${i},"op":"open","sid":${goQuote(st.sid)},"version":${s.version}${this.versionsJSON(pins)}}`,
    );
  }

  private stepOn(i: number, st: SimStep): void {
    const ss = this.sessions.get(st.sid);
    if (ss === undefined) {
      this.emit(`{"i":${i},"op":"on","sid":${goQuote(st.sid)},"skip":true}`);
      return;
    }
    let r: { n: number; affected: number; hash: string; cost: bigint };
    try {
      r = simQuery(ss.s, st.sql);
    } catch (e) {
      const code = errCode(e);
      if (code.startsWith("non-engine")) {
        this.fail(i, code);
        return;
      }
      this.emit(`{"i":${i},"op":"on","sid":${goQuote(st.sid)},"error":${goQuote(code)}}`);
      if (code === "XX001") this.fail(i, "corruption: a statement reported XX001: " + errText(e));
      return;
    }
    this.emit(
      `{"i":${i},"op":"on","sid":${goQuote(st.sid)},"rows":${r.n},"affected":${r.affected},` +
        `"hash":"${r.hash}","cost":${r.cost}}`,
    );
  }

  // digest is the logical digest of what s sees of database d: the catalog relations plus every
  // table's rows, all rendered and sorted, folded with FNV-1a. null if any query failed (an aborted
  // block); digestErr then holds that error.
  private digest(s: Session, d: SimDB): string | null {
    this.digestErr = null;
    // An armed read fault targets the trace's statements, not the oracle checking them.
    this.fs.oracle = true;
    // The oracle's own reads must not trip a trace session's memory limit.
    const limit = s.maxQueryMemoryBytes;
    if (limit > 0n) s.setMaxQueryMemoryBytes(0n);
    try {
      return this.digestReads(s, qualifier(d));
    } finally {
      if (limit > 0n) s.setMaxQueryMemoryBytes(limit);
      this.fs.oracle = false;
    }
  }

  // checkLive runs the live integrity checker with read faults suspended, like every oracle read.
  private checkLive(): void {
    // A page client reads pages only under a pinned transaction; its trees are the owner's pages,
    // which the owner's own live check covers.
    if (coreOf(this.database).client !== null) return;
    this.fs.oracle = true;
    try {
      checkLiveDatabase(this.database);
    } finally {
      this.fs.oracle = false;
    }
  }

  private digestReads(s: Session, q: string): string | null {
    let b = "";
    const tables: string[] = [];
    this.lastDigestText = "";
    const fold = (sql: string): boolean => {
      let rows: ReturnType<Session["query"]>;
      try {
        rows = s.query(sql);
      } catch (e) {
        if (!isEngineError(e)) throw e;
        this.digestErr = e;
        this.lastDigestText = b + sql + "\nERROR: " + errText(e) + "\n";
        return false;
      }
      const rendered: string[] = [];
      try {
        for (const row of rows) {
          const cells: string[] = [];
          for (const v of row) {
            try {
              cells.push(s.render(v));
            } catch (e) {
              if (!isEngineError(e)) throw e;
              this.digestErr = e;
              return false;
            }
          }
          if (sql.endsWith("jed_tables")) tables.push(cells[0]!);
          rendered.push(cells.join("\x1f"));
        }
      } catch (e) {
        if (!isEngineError(e)) throw e;
        this.digestErr = e;
        this.lastDigestText = b + sql + "\nERROR: " + errText(e) + "\n";
        return false;
      } finally {
        rows.close();
      }
      rendered.sort(compareUtf8);
      b += sql + "\n" + rendered.join("\n") + "\n\n";
      return true;
    };
    for (const rel of DIGEST_RELATIONS) if (!fold("SELECT * FROM " + q + rel)) return null;
    tables.sort(compareUtf8);
    for (const t of tables) if (!fold(`SELECT * FROM ${q}"${t}"`)) return null;
    this.lastDigestText = b;
    return fnvStringHex(b);
  }

  // committedView is the version and digest of database d a fresh read session sees.
  private committedView(d: SimDB): { v: bigint; dg: string | null } {
    const dg = this.committedDigest(d);
    return { v: this.dbVersion(d), dg };
  }

  // readSession opens a fresh read session, or records why it could not and returns null: the TS
  // session begins (and, under the page service, may re-elect) at open, where Go's defers that to its
  // first read, which the digest then reports.
  private readSession(): Session | null {
    try {
      return this.database.readSession();
    } catch (e) {
      if (!isEngineError(e)) throw e;
      this.digestErr = e;
      this.lastDigestText = "";
      return null;
    }
  }

  private committedDigest(d: SimDB): string | null {
    const dg = this.committedDigestOnce(d);
    if (dg === null && this.reopenStale()) return this.committedDigestOnce(d);
    return dg;
  }

  private committedDigestOnce(d: SimDB): string | null {
    const rs = this.readSession();
    if (rs === null) return null;
    try {
      return this.digest(rs, d);
    } finally {
      rs.close();
    }
  }

  // staleKeyError reports whether the digest that just failed found its process's data key stale: in
  // a service trace of an encrypted database a page client of a database rekeyed, decrypted, or
  // encrypted since it opened is told to reopen (28P04, or 28P02 for a plaintext client —
  // encrypted.md §14).
  private staleKeyError(): boolean {
    if (!this.service || !this.encrypted || this.digestErr === null) return false;
    const code = errCode(this.digestErr);
    return code === "28P04" || code === "28P02";
  }

  // reopenStale restarts the step's process when the digest that just failed found its data key stale
  // (S13), as the host does, with the database's current key. Its sessions end. It reports whether it
  // did, so the caller reads again.
  private reopenStale(): boolean {
    if (!this.staleKeyError()) return false;
    const pid = this.cur;
    try {
      this.closeProc(pid);
    } catch (e) {
      if (!isEngineError(e)) throw e;
      this.fail(this.stepIndex, `reopen p${pid} after a stale key: ${errText(e)}`);
      return false;
    }
    try {
      this.openProc(pid);
    } catch (e) {
      if (e instanceof SimDeadlock || !isEngineError(e)) throw e;
      this.fail(this.stepIndex, `reopen p${pid} after a stale key: ${errText(e)}`);
      return false;
    }
    this.emit(`{"i":${this.stepIndex},"op":"reopened","pid":${pid}}`);
    return true;
  }

  // quiet reports whether the commit being checked ran with nothing that may hold reclamation back: no
  // other session (a reader pins its snapshot), no other process, and no fault.
  private quiet(): boolean {
    return !this.service && this.sessions.size === 0 && this.fs.fault === null;
  }

  private stepCommit(i: number, st: SimStep): void {
    const ss = this.sessions.get(st.sid);
    if (ss === undefined) {
      this.emit(`{"i":${i},"op":"commit","sid":${goQuote(st.sid)},"skip":true}`);
      return;
    }
    this.sessions.delete(st.sid);
    const dbs = this.order();
    const before = dbs.map((d) => {
      // Attached after this session opened: it cannot have written it.
      if (!ss.pins.has(d.name)) return { digest: null as string | null, text: "" };
      const dg = this.digest(ss.s, d);
      return { digest: dg, text: this.lastDigestText };
    });
    let err: unknown = null;
    try {
      ss.s.commit();
    } catch (e) {
      err = e;
    }
    if (err !== null) {
      const code = errCode(err);
      if (code.startsWith("non-engine")) {
        this.fail(i, code);
        return;
      }
      this.emit(`{"i":${i},"op":"commit","sid":${goQuote(st.sid)},"error":${goQuote(code)}}`);
      if (code === "XX001") {
        this.fail(i, "corruption: commit reported XX001: " + errText(err));
        return;
      }
      for (let k = 0; k < dbs.length; k++) {
        const d = dbs[k]!;
        if (!ss.pins.has(d.name)) continue;
        const now = this.dbVersion(d);
        if (now !== d.version) {
          this.fail(i, `a failed commit published version ${now} of ${d.name} (was ${d.version})`);
          return;
        }
        // The commit reached storage, so a crash may still recover its generation (§8.1).
        const f = this.fs.files.get(d.file);
        const dg = before[k]!.digest;
        if (f !== undefined && f.writes > 0 && dg !== null) {
          d.addHistory(d.version + 1n, dg);
          if (d.version + 1n > d.maxAttempted) d.maxAttempted = d.version + 1n;
        }
      }
      return;
    }
    const versions = new Map<string, bigint>();
    for (const d of dbs) versions.set(d.name, this.dbVersion(d));
    let role = "";
    if (this.service) {
      role = coreOf(this.database).client !== null ? `,"role":"client"` : `,"role":"owner"`;
    }
    this.emit(
      `{"i":${i},"op":"commit","sid":${goQuote(st.sid)},"version":${versions.get("main")}` +
        `${this.versionsJSON(versions)}${role}}`,
    );
    const quiet = this.quiet();
    for (let k = 0; k < dbs.length; k++) {
      const d = dbs[k]!;
      // Not attached in this session's process when it opened: it cannot have written it.
      if (!ss.pins.has(d.name)) continue;
      const base = d.version;
      const now = versions.get(d.name)!;
      const inflight = before[k]!;
      if (now === base) {
        if (inflight.digest !== null && inflight.digest !== d.lastDigest) {
          this.fail(
            i,
            `commit succeeded without publishing the transaction's changes to ${d.name}`,
          );
          return;
        }
      } else if (now === base + 1n) {
        if (inflight.digest === null) {
          this.fail(
            i,
            `commit published version ${now} of ${d.name} from a transaction whose reads failed`,
          );
          return;
        }
        let published = this.committedDigest(d);
        if (published === null && this.relaxed && this.fs.fired !== "") {
          // The batch cap's flush failed in this step and revoked the storage, so nothing can be read
          // back; the acknowledged commit is checked by the recovery that follows.
          published = inflight.digest;
        }
        if (
          published === null &&
          this.service &&
          !this.fs.dead &&
          this.digestErr !== null &&
          errCode(this.digestErr) === "08006"
        ) {
          // An armed disconnect landed in the read-back's own frames: read it back again.
          published = this.committedDigest(d);
        }
        if (published === null && this.service && this.fs.dead) {
          // The owner died later in this step (its maintenance commit hit the fault), so nothing can be
          // read back through it; the acknowledged commit is checked by the recovery that follows.
          published = inflight.digest;
        }
        if (published === null || published !== inflight.digest) {
          this.diagnostics = new Map([
            ["before-commit.txt", inflight.text],
            ["after-commit.txt", this.lastDigestText],
          ]);
          this.fail(
            i,
            `version ${now} of ${d.name} does not contain what its transaction saw before commit`,
          );
          return;
        }
        d.addHistory(now, inflight.digest);
        d.version = now;
        d.lastDigest = inflight.digest;
        if (now > d.maxAttempted) d.maxAttempted = now;
        // Acknowledged under synchronous = on; a relaxed client's commit joins the owner's batch (§8.2).
        if (!this.relaxed) d.floor = now;
        // A page client planned against the owner's batch at its begin_write, which is where the owner
        // flushes a batch past its deadline (validated-cow.md §4.1): its commit joins the batch, however
        // late.
        if (d.due && (serviceCoreOf(this.database, d)?.client ?? null) !== null) {
          d.due = false;
          d.batchOpen = true;
          d.batchPending = true;
        }
        this.checkGrowth(i, d, quiet);
        if (this.violation !== "") return;
        if (this.service) {
          this.serviceCommitted(i, d, base, now, inflight.digest);
          if (this.violation !== "") return;
        }
      } else {
        this.fail(i, `commit jumped ${d.name} from version ${base} to ${now}`);
        return;
      }
    }
    if (this.relaxed && this.fs.fired !== "") {
      return; // a failed cap flush revoked the storage; the recovery that follows checks it
    }
    try {
      this.checkLive();
    } catch (e) {
      this.fail(i, "after commit: " + errText(e));
    }
  }

  // serviceCommitted runs the page-service checks after a commit of main published version now over
  // base (S8). A page client's commit must obey the commit-role rule (page-service.md §6): it never
  // rebuilds the free list, so the free list it persists is a subset of its base's. And an owner may
  // follow a client's commit with a maintenance commit — the unchanged snapshot at the next versions —
  // which joins the history with the same contents.
  private serviceCommitted(i: number, d: SimDB, base: bigint, now: bigint, digest: string): void {
    const c = serviceCoreOf(this.database, d);
    if (c === null || c.client === null) return;
    const image = this.image(d);
    const before = freeListOf(image, this.pageSize, base);
    const after = freeListOf(image, this.pageSize, now);
    if (before !== null && after !== null) {
      const was = new Set(before);
      for (const pg of after) {
        if (!was.has(pg)) {
          this.fail(
            i,
            `commit-role rule: a page client's commit (version ${now}) freed page ${pg}, which its ` +
              `base's free list does not hold`,
          );
          return;
        }
      }
    }
    if (this.fs.dead) {
      // The owner died later in this step; it may have been writing a maintenance commit, which
      // recovery may select: the same contents at the next version.
      d.addHistory(now + 1n, digest);
      if (now + 1n > d.maxAttempted) d.maxAttempted = now + 1n;
      return;
    }
    const owner = this.ownerPidOf(d);
    if (owner < 0) return;
    const ownerDb = this.procs.get(owner)!.db;
    const ov = d.name === "main" ? versionOf(ownerDb) : attachedVersionOf(ownerDb, d);
    if (ov <= now) return;
    for (let v = now + 1n; v <= ov; v++) d.addHistory(v, digest);
    d.version = ov;
    if (ov > d.maxAttempted) d.maxAttempted = ov;
    if (!this.relaxed) d.floor = ov; // the maintenance commit is an owner commit: batched under off
    if (d.name === "main") this.emit(`{"i":${i},"op":"maintenance","version":${ov}}`);
    else {
      this.emit(`{"i":${i},"op":"maintenance","db":${goQuote(d.name)},"version":${ov}}`);
    }
  }

  // engineFlushed reports whether the process writing database d holds no relaxed commit pending a
  // flush — no pending set, no adopted generation awaiting stabilization, no failed barrier — so its
  // published version is the one it treats as durable (validated-cow.md §4). Under the page service
  // the owner writes the file; with no owner running, nothing is claimed.
  private engineFlushed(d: SimDB): boolean {
    let db = this.db;
    if (this.service) {
      const owner = this.ownerPidOf(d);
      if (owner < 0) return false;
      db = this.procs.get(owner)!.db;
    }
    if (db === null) return false;
    const core = coreOf(db);
    const st = d.name === "main" ? core.storage : core.attachments.get(d.name)?.storage;
    if (st === undefined || st.paging === null) return false;
    return st.paging.batchFlushed();
  }

  // enginePending reports whether the process writing database d holds a non-empty pending set — a
  // relaxed batch not yet flushed (validated-cow.md §4). Not run under the page service.
  private enginePending(d: SimDB): boolean {
    if (this.service || this.db === null) return false;
    const core = coreOf(this.db);
    const st = d.name === "main" ? core.storage : core.attachments.get(d.name)?.storage;
    if (st === undefined || st.paging === null) return false;
    return st.paging.hasPending();
  }

  // checkTruncated checks trailing truncation against batched durability (§8.3, validated-cow.md §4).
  // The file never shrinks below the durable floor's high-water: while a relaxed batch is pending the
  // floor is the only generation recovery is sure to find, so a shrink before the flush must not cut
  // its pages. And once the engine holds nothing pending again, a shrink that a relaxed commit deferred
  // has happened: the file is at most one growth step past the published high-water.
  private checkTruncated(i: number, d: SimDB): boolean {
    const f = this.fs.files.get(d.file);
    if (f === undefined) return true;
    const length = f.cache.length;
    const floor = metaOf(f.cache, this.pageSize, d.floor);
    if (floor !== null && floor.pageCount * this.pageSize > length) {
      this.fail(
        i,
        `trailing truncation: ${d.name}'s file is ${length} bytes, shorter than its durable version ` +
          `${d.floor}'s ${floor.pageCount} pages`,
      );
      return false;
    }
    if (!d.shrinkDue) return true;
    if (this.fs.dead || this.fs.fired !== "" || this.fs.fault !== null) {
      d.shrinkDue = false; // a crash or fault may have cut the flush short
      return true;
    }
    if (!this.engineFlushed(d)) return true;
    d.shrinkDue = false;
    const meta = metaOf(f.cache, this.pageSize, d.version);
    if (meta === null) return true;
    const pc = meta.pageCount;
    const limit = (pc + growthStep(pc, this.pageSize)) * this.pageSize;
    if (length > limit) {
      this.fail(
        i,
        `trailing truncation: ${d.name} flushed a batch that lowered its high-water to ${pc} pages but ` +
          `its file is ${length} bytes (at most ${limit})`,
      );
      return false;
    }
    return true;
  }

  // --- bounded growth (simulation-testing.md §8.3) ----------------------------------------------

  // allocator is database d's page high-water and free-list length in the running process — the
  // allocator state the next commit draws from — and where the free list's trailing run below the
  // high-water starts (the high-water when its top page is not free; format.md *Trailing truncation*).
  private allocator(d: SimDB): { pageCount: number; free: number; trail: number } {
    const core = coreOf(this.database);
    const st = d.name === "main" ? core.storage : core.attachments.get(d.name)?.storage;
    if (st === undefined) return { pageCount: 0, free: 0, trail: 0 };
    const trail = trailingRun(st.freePages, st.pageCount).start;
    return { pageCount: st.pageCount, free: st.freePages.length, trail };
  }

  // observeGrowth starts a new bounded-growth lifetime for d (an open, a recovery, a compaction, an
  // attach). The engine seeds its reclamation trigger with the page count minus the free list
  // (format.md *Reclamation*), so a file whose dead pages are not all listed is reclaimed only after
  // it doubles.
  private observeGrowth(d: SimDB): void {
    const { pageCount, free, trail } = this.allocator(d);
    d.high = pageCount;
    d.free = free;
    d.trail = trail;
    d.lacBound = (pageCount - free) >>> 0;
    d.last = { reclaimed: false, high: 0, free: 0 };
  }

  // checkGrowth checks the reader-aware bounded-growth invariant after a commit published a new
  // version of d (simulation-testing.md §8.3). With no reader pinned, no other process, and no fault,
  // the engine reclaims in the commit once the pages off its free list pass compact_growth × the live
  // count at its last reclamation (memory.md §8.4); readers legitimately hold reclamation back, so a
  // commit with one open is not checked. A commit only adds pages off the list (each page it allocates
  // leaves the list or grows the file), so the count it began with is a lower bound. Two checks follow:
  //   - a quiet commit that began with more pages off the list than max(compact_min_pages,
  //     compact_growth × an upper bound on that live count) must have reclaimed: every page below the
  //     high-water is meta, live, free, or written by the commit itself (its manifest and free-list
  //     pages);
  //   - the next quiet commit reuses that free list before it grows the file.
  private checkGrowth(i: number, d: SimDB, quiet: boolean): void {
    if (this.service) return;
    const meta = metaOf(this.image(d), this.pageSize, d.version);
    if (meta === null) return;
    const pc = meta.pageCount;
    const live = meta.live;
    const { free, trail } = this.allocator(d);
    const file = this.fs.files.get(d.file)!;
    let written = 0;
    let top = 0;
    for (const pg of file.pages) {
      if (pg >= 2) {
        written++;
        top = Math.max(top, pg + 1);
      }
    }
    // Trailing truncation (§8.3): a quiet commit passes the reuse gate, so its tree pages take the
    // lowest free pages, whatever of the old trailing run they leave is truncated, and every later page
    // comes from the high-water at the run's start. A commit inside a relaxed batch never lowers the
    // high-water (validated-cow.md §4), so it only grows it to what it wrote.
    if (quiet && d.batchPending && pc !== Math.max(d.high, top)) {
      this.fail(
        i,
        `trailing truncation: ${d.name} has ${pc} pages after a commit inside a relaxed batch that ` +
          `wrote up to page ${top}, from ${d.high} pages`,
      );
      return;
    }
    if (quiet && !d.batchPending && pc !== Math.max(d.trail, top)) {
      this.fail(
        i,
        `trailing truncation: ${d.name} has ${pc} pages after a quiet commit that wrote up to page ` +
          `${top}, from ${d.high} pages whose free list's trailing run began at ${d.trail}`,
      );
      return;
    }
    if (quiet && pc < d.high && this.relaxed) {
      // The shrink waits for the batch's flush (validated-cow.md §4): checked when the engine next holds
      // nothing pending (checkTruncated).
      d.shrinkDue = true;
    } else if (quiet && pc < d.high) {
      const limit = (pc + growthStep(pc, this.pageSize)) * this.pageSize;
      if (file.cache.length > limit) {
        this.fail(
          i,
          `trailing truncation: ${d.name} lowered its high-water to ${pc} pages but its file is ` +
            `${file.cache.length} bytes (at most ${limit})`,
        );
        return;
      }
    }
    const before = d.last;
    if (d.batchOpen) {
      // A commit inside a relaxed batch neither reuses nor frees the batch's pages (validated-cow.md
      // §4); only the bounds carry forward.
      d.high = pc;
      d.free = free;
      d.trail = trail;
      d.lacBound = Math.max(d.lacBound, live + written);
      d.last = { reclaimed: false, high: 0, free: 0 };
      return;
    }
    if (
      quiet &&
      before.reclaimed &&
      pc > before.high &&
      pc - before.high > written - Math.min(written, before.free)
    ) {
      this.fail(
        i,
        `bounded growth: ${d.name} grew from ${before.high} to ${pc} pages writing ${written}, ` +
          `with ${before.free} free pages to reuse`,
      );
      return;
    }
    let reclaimed = false;
    if (quiet && d.high - d.free > Math.max(COMPACT_MIN_PAGES, COMPACT_GROWTH * d.lacBound)) {
      reclaimed = true;
      if (pc < 2 + live + free || pc - 2 - live - free > written) {
        this.fail(
          i,
          `bounded growth: ${d.name} has ${pc} pages, ${live} live and ${free} free, after a commit ` +
            `that wrote ${written} must have reclaimed every dead page`,
        );
        return;
      }
    }
    d.high = pc;
    d.free = free;
    d.trail = trail;
    d.lacBound = Math.max(d.lacBound, live + written);
    d.last = { reclaimed, high: pc, free };
  }

  private stepEnd(i: number, st: SimStep): void {
    const ss = this.sessions.get(st.sid);
    if (ss === undefined) {
      this.emit(`{"i":${i},"op":${goQuote(st.kind)},"sid":${goQuote(st.sid)},"skip":true}`);
      return;
    }
    this.sessions.delete(st.sid);
    if (st.kind === "rollback") {
      try {
        ss.s.rollback();
      } catch (e) {
        this.emit(
          `{"i":${i},"op":"rollback","sid":${goQuote(st.sid)},"error":${goQuote(errCode(e))}}`,
        );
        return;
      }
    } else {
      // Snapshot isolation: a reader still sees exactly the version of every database it pinned,
      // however many commits, reclamations, and page reuses happened since.
      let lost = false;
      if (!ss.write) {
        for (const d of this.order()) {
          const pin = ss.pins.get(d.name);
          if (pin === undefined) continue;
          const dg = this.digest(ss.s, d);
          if (dg === null && this.service && errCode(this.digestErr) === "08006") {
            // Under the page service a read transaction open across a change of its process's role
            // fails 08006 (spec/pageservice/README.md §6.5): it never sees other contents.
            lost = true;
            break;
          }
          if (dg === null || !d.inHistory(pin, dg)) {
            this.fail(i, `isolation: reader ${st.sid} no longer sees version ${pin} of ${d.name}`);
            break;
          }
        }
      }
      closeQuietly(ss.s);
      if (lost) {
        this.emit(`{"i":${i},"op":${goQuote(st.kind)},"sid":${goQuote(st.sid)},"lost":true}`);
        return;
      }
    }
    this.emit(`{"i":${i},"op":${goQuote(st.kind)},"sid":${goQuote(st.sid)}}`);
  }

  // stepCompact runs host compaction (api.md §2.6) of database name: the committed snapshot rewritten
  // as a fresh image at the next version, through the simulated filesystem's temp file, rename, and
  // directory barrier. Its contents are unchanged, so a crash may recover either version with the
  // same digest.
  // rekey (S12) is compaction under simulation key rekey's new data key: the same version and
  // contents rules.
  // stepRekey is `rekey <n>|plain [<db>]` (S12–S13): compaction under a new data key for simulation
  // key target, which encrypts a plaintext database, or with -1 a decryption.
  private stepRekey(i: number, name: string, target: number): void {
    if (!this.encrypted) {
      this.emit(`{"i":${i},"op":"rekey","skip":true}`);
      return;
    }
    this.stepCompact(i, name, true, target);
  }

  private stepCompact(i: number, name: string, rekey: boolean, target: number): void {
    const op = rekey ? "rekey" : "compact";
    const d = this.dbs.get(name);
    if (d === undefined || this.dbVersion(d) === 0n) {
      this.emit(`{"i":${i},"op":"${op}","db":${goQuote(name)},"skip":true}`);
      return;
    }
    const base = d.version;
    d.addHistory(base + 1n, d.lastDigest);
    if (base + 1n > d.maxAttempted) d.maxAttempted = base + 1n;
    let err: unknown = null;
    try {
      if (rekey) {
        d.keyChange = { old: d.key, next: target, entryPending: !this.fs.entryDurable(d.file) };
        this.database.rekey(name, simCredential(target) ?? null);
        d.key = target;
      } else {
        this.database.compact(name);
      }
    } catch (e) {
      err = e;
    }
    const now = this.dbVersion(d);
    const dbField = name !== "main" ? `,"db":${goQuote(name)}` : "";
    if (err !== null) {
      const code = errCode(err);
      if (code.startsWith("non-engine")) {
        this.fail(i, code);
        return;
      }
      this.emit(`{"i":${i},"op":"${op}"${dbField},"error":${goQuote(code)}}`);
      if (code === "XX001") this.fail(i, `corruption: ${op} reported XX001: ` + errText(err));
      else if (now > base || (now !== base && !this.service))
        // (A page client's view may lag the owner's until its next begin.)
        this.fail(i, `a failed ${op} published version ${now} of ${name} (was ${base})`);
      return;
    }
    this.emit(`{"i":${i},"op":"${op}"${dbField},"version":${now}}`);
    if (now !== base + 1n) {
      this.fail(i, `${op} moved ${name} from version ${base} to ${now}`);
      return;
    }
    const dg = this.committedDigest(d);
    if (dg === null || dg !== d.lastDigest) {
      this.fail(i, `${op} changed the contents of ${name}`);
      return;
    }
    try {
      this.checkLive();
    } catch (e) {
      this.fail(i, `after ${op}: ` + errText(e));
      return;
    }
    d.version = now;
    d.floor = now; // the rename and the directory barrier completed
    this.observeGrowth(d);
  }

  // stepBackup is `backup page_identical|compacted [p<N>]` (spec/design/page-service.md §9): the
  // process backs main up into a new file through the simulated filesystem, while every other session
  // keeps its pins and its writer gate. A backup that fails leaves no destination. One that succeeds is
  // checked at once, as a new process would open it: its version is the pinned snapshot's
  // (page-identical) or the one after it (compacted), the snapshot is the newest committed
  // generation, its contents are that generation's, and the integrity checker accepts the image. Its
  // image hash makes the cores' backups byte-identical (§8.4).
  private stepBackup(i: number, st: SimStep): void {
    const d = this.main();
    this.backups++;
    const dest = `${d.file}.backup${this.backups}`;
    try {
      backupForTesting(this.database, dest, st.mode === "page_identical");
    } catch (e) {
      if (e instanceof SimDeadlock) throw e;
      const code = errCode(e);
      if (code.startsWith("non-engine")) {
        this.fail(i, code);
        return;
      }
      this.emit(`{"i":${i},"op":"backup","form":${goQuote(st.mode)},"error":${goQuote(code)}}`);
      if (code === "XX001") this.fail(i, "corruption: backup reported XX001: " + errText(e));
      else if (this.fs.files.has(dest)) this.fail(i, "a failed backup left its destination");
      return;
    }
    const f = this.fs.files.get(dest);
    if (f === undefined) {
      this.fail(i, "a successful backup left no destination");
      return;
    }
    const image = f.cache.slice();
    if (this.imagePrefix !== "") {
      writeFileSync(`${this.imagePrefix}.step${i}.backup.img`, image);
    }
    let copy: Database;
    try {
      // The copy opens with the database's credential at the time of the backup (encrypted.md §13).
      const env = this.procEnv();
      const pager = Pager.fromStore(new MemoryBlockStore(image.slice()));
      const codec = runSync(unlockPagerSteps(pager, this.credential(d), env));
      copy = Database.fromEngine(
        loadEnginePaged(
          new SharedPaging(pager, cacheLeaves(DEFAULT_CACHE_BYTES, pager.pageSize), codec),
          env,
        ),
        null,
      );
    } catch (e) {
      let opens = -2;
      for (let k = -1; k < 4; k++) if (this.unlocks(image, k)) opens = k;
      this.fail(
        i,
        `the backup does not open with key ${d.key}: ${errText(e)} (key ${opens} opens it)`,
      );
      return;
    }
    let v: bigint;
    let dg: string | null;
    try {
      v = versionOf(copy);
      const rs = copy.readSession();
      try {
        dg = this.digest(rs, d);
      } finally {
        rs.close();
      }
    } finally {
      copy.close();
    }
    const snapshot = st.mode === "compacted" ? v - 1n : v;
    if (dg === null) {
      this.fail(i, "the backup cannot be read: " + errText(this.digestErr));
      return;
    }
    // A dead owner's batch may be lost back to the floor (§8.2): a backup that promotes its process,
    // or reaches a new owner, may then copy any version from the floor up.
    if (snapshot < d.version && (!d.ownerLost || snapshot < d.floor)) {
      this.fail(i, `the backup copied version ${snapshot}, older than the committed ${d.version}`);
      return;
    }
    if (!d.inHistory(snapshot, dg)) {
      this.fail(i, `the backup holds contents (digest ${dg}) version ${snapshot} never had`);
      return;
    }
    if (d.ownerLost) {
      // The backup's pin is the first look at main since its owner died: what it copied is now the
      // committed generation, as observe records for a session.
      d.version = snapshot;
      d.lastDigest = dg;
      d.ownerLost = false;
    }
    let counts: [number, number, number];
    try {
      counts = checkImage(image, v, this.credential(d));
    } catch (e) {
      this.fail(i, "backup integrity: " + errText(e));
      return;
    }
    this.backupsOK.push({ n: this.backups, file: dest, version: v, digest: dg, key: d.key });
    const [live, pages, free] = counts;
    this.emit(
      `{"i":${i},"op":"backup","form":${goQuote(st.mode)},"version":${v},"digest":${goQuote(dg)},` +
        `"live":${live},"pages":${pages},"free":${free},` +
        `"image":"${imageHash(image, pages, this.pageSize)}"}`,
    );
  }

  // stepAttach attaches file database name to the running process (S4), first creating its file
  // through the simulated filesystem if it does not exist — create's temp file, sync, rename, and
  // directory barrier, any of which a fault may interrupt. Already attached, it only reports.
  private stepAttach(i: number, name: string): void {
    // Attaching takes the writer gate. The generator never attaches while a writer is open; a trace
    // that does (a shrinking artifact) would wait forever in a threaded core, so it is invalid.
    const writers = [...this.sessions]
      .filter(([, ss]) => ss.write)
      .map(([sid]) => sid)
      .sort();
    if (writers.length > 0) {
      this.fail(i, `attach ${name} while ${writers[0]} holds the writer gate`);
      return;
    }
    let d = this.dbs.get(name);
    if (
      d !== undefined &&
      this.dbVersion(d) !== 0n &&
      (!this.service || this.attachedInAll(name))
    ) {
      this.emit(`{"i":${i},"op":"attach","db":${goQuote(name)},"version":${d.version}}`);
      return;
    }
    if (d === undefined) {
      d = new SimDB(name, name + ".jed");
      this.dbs.set(name, d);
    }
    if (!this.fs.files.has(d.file)) {
      // A fresh file is version 1, empty. Until create returns it may vanish in a crash (floor 0).
      d.history = new Map();
      d.addHistory(1n, emptyDigest(d));
      d.version = 1n;
      d.lastDigest = emptyDigest(d);
      d.floor = 0n;
      d.maxAttempted = 1n;
      d.key = this.createKey();
      try {
        closeEngine(
          createVia(this.fs, d.file, {
            pageSize: this.pageSize,
            credential: this.credential(d),
            environment: this.newEnv(this.cur),
          }),
        );
      } catch (e) {
        this.attachFailed(i, name, e);
        return;
      }
      d.floor = 1n; // create returned: the file and its directory entry are durable
    }
    if (this.service) {
      if (!this.attachEverywhere(i, name)) return;
    } else {
      try {
        this.attach(name);
      } catch (e) {
        this.attachFailed(i, name, e);
        return;
      }
    }
    const v = this.dbVersion(d);
    const dg = this.committedDigest(d);
    if (!this.checkRecovered(i, d, v, dg, "attached")) return;
    this.observeGrowth(d);
    this.emit(`{"i":${i},"op":"attach","db":${goQuote(name)},"version":${v}}`);
  }

  // attachEverywhere attaches file database name in every running process of a service trace
  // (README.md §6.6): main's owner first — so it owns the file too, and one process owns every
  // database — then the others in process order, each a page client of it. With no owner of main, the
  // lowest process's read begin first re-elects it. A process that already has it attached is skipped.
  // It leaves the attaching owner as the step's process.
  private attachEverywhere(i: number, name: string): boolean {
    let first = this.ownerPid();
    if (first < 0) {
      first = this.livePids()[0]!;
      this.selectProc(first);
      const dg = this.committedDigest(this.main());
      if (!this.observe(i, `attaching p${first}`, versionOf(this.database), dg)) return false;
      this.net.pump();
    }
    const order = [first, ...this.livePids().filter((pid) => pid !== first)];
    for (const pid of order) {
      this.selectProc(pid);
      if (coreOf(this.database).attachments.has(name)) continue;
      let err: unknown = null;
      try {
        this.attach(name);
      } catch (e) {
        err = e;
      }
      this.net.pump();
      if (err !== null) {
        this.selectProc(first);
        this.attachFailed(i, name, err);
        return false;
      }
    }
    this.selectProc(first);
    return true;
  }

  // attachedInAll reports whether every running process has attachment name attached.
  private attachedInAll(name: string): boolean {
    for (const pid of this.livePids()) {
      if (!coreOf(this.procs.get(pid)!.db).attachments.has(name)) return false;
    }
    return true;
  }

  private attachFailed(i: number, name: string, e: unknown): void {
    if (e instanceof SimDeadlock) throw e;
    const code = errCode(e);
    if (code.startsWith("non-engine") || code === "XX001") {
      this.fail(i, `attach ${name}: ${errText(e)}`);
      return;
    }
    this.emit(`{"i":${i},"op":"attach","db":${goQuote(name)},"error":${goQuote(code)}}`);
  }

  private stepCheck(i: number): void {
    const entries: string[] = [];
    let mainLine = "";
    for (const d of this.order()) {
      if (this.service && d.name !== "main" && this.dbVersion(d) === 0n) {
        // This process is not attached to it: a faulted attach killed the process attaching it before
        // this one did; the next attach step repairs that.
        continue;
      }
      const { v, dg } = this.committedView(d);
      if (this.service) {
        // Another process may have died leaving a newer complete generation this one now adopts.
        if (!this.observeDB(i, d, "check", v, dg)) return;
      } else if (dg === null || v !== d.version || dg !== d.lastDigest) {
        this.fail(i, `a read session does not see the last committed version of ${d.name}`);
        return;
      }
      const image = this.image(d);
      let counts: [number, number, number];
      try {
        counts = checkImage(image ?? new Uint8Array(), d.version, this.credential(d));
      } catch (e) {
        this.fail(i, `integrity of ${d.name}: ` + errText(e));
        return;
      }
      const [live, pages, free] = counts;
      const body =
        `"version":${d.version},"digest":${goQuote(dg!)},"live":${live},"pages":${pages},` +
        `"free":${free},"image":"${imageHash(image!, pages, this.pageSize)}"`;
      if (d.name === "main") mainLine = body;
      else entries.push(`${goQuote(d.name)}:{${body}}`);
    }
    try {
      this.checkLive();
    } catch (e) {
      this.fail(i, "live integrity: " + errText(e));
      return;
    }
    this.emit(`{"i":${i},"op":"check",${mainLine}${dbsJSON(entries)}}`);
  }

  // closeFlushed raises each database's floor to its published version after every process closed
  // cleanly under synchronous = off, when the close left every byte of the file and its directory
  // entry durable: a clean close flushes the batch (validated-cow.md §4). A generation a recovered
  // process adopted and never had to stabilize (it wrote nothing) may still be pending, and keeps its
  // floor (§8.2). So does a database whose owner died: what it published may be gone until a process
  // observes the database again.
  private closeFlushed(): void {
    if (!this.relaxed) return;
    for (const d of this.order()) {
      const f = this.fs.files.get(d.file);
      if (f === undefined || d.ownerLost) continue;
      if (!f.hasPending() && this.fs.entryDurable(d.file) && d.version > d.floor) {
        d.floor = d.version;
      }
    }
  }

  // stepReopen ends every session cleanly, closes the Database, and reopens it: the result must be
  // exactly the last committed version of every database.
  private stepReopen(i: number): boolean {
    for (const pid of this.livePids()) {
      try {
        this.closeProc(pid);
      } catch (e) {
        if (!isEngineError(e)) throw e;
        this.fail(i, "close: " + errText(e));
        return false;
      }
    }
    // Close flushed every batch, so a shrink a relaxed commit deferred has happened, and the floor the
    // file is held to is the version it flushed (validated-cow.md §4), not the one before it.
    this.closeFlushed();
    for (const d of this.order()) if (!this.checkTruncated(i, d)) return false;
    this.fs.processDeath();
    try {
      this.open();
    } catch (e) {
      this.fail(i, "reopen failed: " + errText(e));
      return false;
    }
    const entries: string[] = [];
    let mainV = 0n;
    let mainD = "";
    for (const d of this.order()) {
      if (
        this.dbVersion(d) === 0n &&
        d.name !== "main" &&
        this.service &&
        d.floor === 0n &&
        !this.fs.files.has(d.file)
      ) {
        // A faulted attach killed its owner before create returned (S8 kills only the owner, so no
        // recovery ran to forget it): the file may legitimately be gone.
        this.dbs.delete(d.name);
        continue;
      }
      if (this.dbVersion(d) === 0n) {
        this.fail(i, `a clean reopen lost attachment ${d.name}`);
        return false;
      }
      const v = this.dbVersion(d);
      const dg = this.committedDigest(d);
      if (this.service) {
        // A process killed mid-commit may have left a complete generation no survivor began on yet.
        if (!this.observeDB(i, d, "reopened p0", v, dg)) return false;
      } else if (v !== d.version || dg === null || dg !== d.lastDigest) {
        this.fail(
          i,
          `a clean reopen returned version ${v} of ${d.name} (digest ${dg ?? ""}), want version ` +
            `${d.version} (digest ${d.lastDigest})`,
        );
        return false;
      }
      this.observeGrowth(d);
      if (d.name === "main") {
        mainV = v;
        mainD = dg!;
      } else entries.push(`${goQuote(d.name)}:{"version":${v},"digest":${goQuote(dg!)}}`);
    }
    this.emit(
      `{"i":${i},"op":"reopen","version":${mainV},"digest":${goQuote(mainD)}${dbsJSON(entries)}}`,
    );
    return true;
  }

  // checkRecovered checks a database's version and contents after a recovery or an attach against
  // its history and durability floor (§8.1–8.2).
  private checkRecovered(i: number, d: SimDB, v: bigint, dg: string | null, what: string): boolean {
    if (dg === null) {
      this.fail(i, `${what}: version ${v} of ${d.name} is unreadable: ${errText(this.digestErr)}`);
    } else if (v < d.floor) {
      this.fail(
        i,
        `durability: ${what} version ${v} of ${d.name}, but version ${d.floor} was durable`,
      );
    } else if (v > d.maxAttempted) {
      this.fail(
        i,
        `${what}: version ${v} of ${d.name} was never attempted (latest attempted ${d.maxAttempted})`,
      );
    } else if (!d.inHistory(v, dg)) {
      this.fail(
        i,
        `${what}: version ${v} of ${d.name} has contents (digest ${dg}) no transaction produced`,
      );
    }
    if (this.violation !== "") return false;
    d.version = v;
    d.lastDigest = dg!;
    return true;
  }

  // stepChangeKey is `change_key <n> [<db>]` (S12–S13, encrypted.md §5): the credential of main or a
  // file attachment changes to simulation key n. Only the key block is written, so no version or
  // content moves. A plaintext database refuses it (28P03).
  private stepChangeKey(i: number, name: string, n: number): void {
    const d = this.dbs.get(name);
    if (!this.encrypted || d === undefined || this.dbVersion(d) === 0n) {
      this.emit(`{"i":${i},"op":"change_key","db":${goQuote(name)},"skip":true}`);
      return;
    }
    const dbField = name !== "main" ? `,"db":${goQuote(name)}` : "";
    const base = this.dbVersion(d);
    d.keyChange = { old: d.key, next: n, entryPending: !this.fs.entryDurable(d.file) };
    try {
      this.database.changeCredential(name, SIM_KEYS[n]!);
      d.key = n;
      this.emit(`{"i":${i},"op":"change_key"${dbField},"key":${n}}`);
    } catch (e) {
      if (e instanceof SimDeadlock) throw e;
      const code = errCode(e);
      if (code.startsWith("non-engine")) {
        this.fail(i, code);
        return;
      }
      this.emit(`{"i":${i},"op":"change_key"${dbField},"error":${goQuote(code)}}`);
      if (code === "XX001") this.fail(i, "corruption: change_key reported XX001: " + errText(e));
    }
    if (this.dbVersion(d) !== base) {
      this.fail(i, `a credential change published a version of ${name}`);
    }
  }

  // recover abandons the crashed process — its sessions and Database — and opens the disk as a new
  // process would, then checks every database's recovered generation against its history and
  // durability floor (§8.1–8.2) and its image against the integrity checker (§8.3).
  private recover(i: number, fired: string): boolean {
    for (const pid of this.livePids()) this.dropProc(pid);
    this.fs.processDeath();
    const images = new Map<string, Uint8Array | null>();
    for (const d of this.order()) {
      const image = this.image(d);
      images.set(d.name, image);
      if (d.name !== "main" && image === null) {
        // A crash during the attachment's create: allowed only while create had not returned.
        if (d.floor > 0n) {
          this.fail(
            i,
            `durability: attachment ${d.name}'s file is gone, but version ${d.floor} was durable`,
          );
          return false;
        }
        this.dbs.delete(d.name);
        continue;
      }
      if (this.imagePrefix !== "") {
        const suffix = d.name !== "main" ? "." + d.name : "";
        writeFileSync(`${this.imagePrefix}.step${i}${suffix}.img`, image ?? new Uint8Array());
      }
    }
    for (const d of this.order()) {
      if (!this.settleKey(i, d, images.get(d.name) ?? null)) {
        this.crashImage = images.get(d.name) ?? null;
        return false;
      }
    }
    try {
      this.open();
    } catch (e) {
      this.crashImage = images.get("main") ?? null;
      this.fail(i, "recovery: open failed: " + errText(e));
      return false;
    }
    const entries: string[] = [];
    let mainLine = "";
    for (const d of this.order()) {
      const image = images.get(d.name) ?? null;
      const v = this.dbVersion(d);
      const dg = this.committedDigest(d);
      if (!this.checkRecovered(i, d, v, dg, "recovered")) {
        this.crashImage = image;
        return false;
      }
      let counts: [number, number, number];
      try {
        counts = checkImage(image ?? new Uint8Array(), v, this.credential(d));
      } catch (e) {
        this.crashImage = image;
        this.fail(i, `recovery integrity of ${d.name}: ` + errText(e));
        return false;
      }
      const [live, pages, free] = counts;
      this.observeGrowth(d);
      const body =
        `"recovered":${v},"digest":${goQuote(dg!)},"live":${live},"pages":${pages},` +
        `"free":${free},"image":"${imageHash(image!, pages, this.pageSize)}"`;
      if (d.name === "main") mainLine = body;
      else entries.push(`${goQuote(d.name)}:{${body}}`);
    }
    this.emit(`{"i":${i},"op":"crash","fired":${goQuote(fired)},${mainLine}${dbsJSON(entries)}}`);
    return true;
  }

  // stepCorrupt is `corrupt flips=N [reseal=1]` (simulation-testing.md §6.3): every process ends
  // cleanly; bits flip in durable body pages of the main database; a new process opens it and reads
  // everything; then the bits are repaired and the database must reopen exactly as it was. Without
  // reseal a flip breaks its page's CRC, so every outcome must be XX001 or the right rows — never
  // wrong rows. With reseal the CRC is recomputed, so only the engine's structural checks stand in
  // the way: any engine error, or any rows, is allowed, but never a non-engine error.
  private stepCorrupt(i: number, st: SimStep): boolean {
    const reseal = st.params.get("reseal") === "1";
    for (const pid of this.livePids()) {
      try {
        this.closeProc(pid);
      } catch (e) {
        if (!isEngineError(e)) throw e;
        this.fail(i, "close: " + errText(e));
        return false;
      }
    }
    this.fs.processDeath();
    const m = this.main();
    const file = this.fs.main()!;
    const meta = metaOf(file.cache, this.pageSize, m.version);
    if (meta === null) {
      this.fail(i, `corrupt: no meta holds version ${m.version}`);
      return false;
    }
    const flips = file.corrupt(i, intParam(st, "flips"), meta.pageCount, reseal);
    const outcome = (e: unknown): string | null => {
      const code = errCode(e);
      if (code.startsWith("non-engine")) {
        this.fail(i, "corrupt: " + code);
        return null;
      }
      if (code !== "XX001" && !reseal) {
        this.fail(i, `corrupt: a flipped checksum surfaced as ${code}, not XX001: ${errText(e)}`);
        return null;
      }
      return code;
    };
    let opened = "ok";
    let read = "-";
    let openErr: unknown = null;
    try {
      this.openProc(0);
    } catch (e) {
      if (e instanceof SimDeadlock) throw e;
      openErr = e;
    }
    if (openErr !== null) {
      const code = outcome(openErr);
      if (code === null) return false;
      opened = code;
    } else {
      read = "ok";
      const v = versionOf(this.database);
      let dg: string | null;
      try {
        dg = this.committedDigest(m);
      } catch (e) {
        // A non-engine throw from a corrupted read is a violation, as Go's digest reports it.
        this.digestErr = e;
        dg = null;
      }
      if (dg === null) {
        const code = outcome(this.digestErr);
        if (code === null) return false;
        read = code;
      } else if (
        !reseal &&
        (!m.inHistory(v, dg) || v > m.version || (v < m.version && v + 1n !== m.version))
      ) {
        // A flip in the newest generation's dirty pages fails its validation, and recovery falls
        // back to the previous generation (validated-cow.md §1), which is intact.
        this.fail(
          i,
          `corrupt: version ${v} read back with contents (digest ${dg}) no transaction produced`,
        );
        return false;
      }
      this.dropProc(0);
    }
    file.repair(flips);
    try {
      this.open();
    } catch (e) {
      this.fail(i, "corrupt: reopen after repair failed: " + errText(e));
      return false;
    }
    const v = versionOf(this.database);
    if (v !== m.version) {
      this.fail(i, `corrupt: after repair version ${v}, want ${m.version}`);
      return false;
    }
    const dg = this.committedDigest(m);
    if (dg === null || dg !== m.lastDigest) {
      this.fail(i, "corrupt: after repair the contents differ");
      return false;
    }
    this.emit(
      `{"i":${i},"op":"corrupt","flipped":${flips.length},"open":${goQuote(opened)},"read":${goQuote(read)}}`,
    );
    return true;
  }

  // stepReplay is `replay <kind>` (simulation-testing.md §8.3 *Replays*, S13): every process ends
  // cleanly; a page of main that a bound pointer of kind names gets back an older durable version of
  // itself (§6.1's archive); a new process opens main and reads every row, and the image checker reads
  // every other reachable page. A page the selected generation's manifest depends on may make recovery
  // fall back to the generation in the other meta slot; any other replay must surface as XX001. Then
  // the page is put back and main must reopen exactly as it was.
  private stepReplay(i: number, kind: string): boolean {
    for (const pid of this.livePids()) {
      try {
        this.closeProc(pid);
      } catch (e) {
        if (!isEngineError(e)) throw e;
        this.fail(i, "close: " + errText(e));
        return false;
      }
    }
    this.closeFlushed();
    this.fs.processDeath();
    const m = this.main();
    const file = this.fs.main();
    const reopen = (): boolean => {
      try {
        this.open();
      } catch (e) {
        this.fail(i, "replay: reopen failed: " + errText(e));
        return false;
      }
      const v = versionOf(this.database);
      if (v !== m.version) {
        this.fail(i, `replay: after the repair version ${v}, want ${m.version}`);
        return false;
      }
      const dg = this.committedDigest(m);
      if (dg === null || dg !== m.lastDigest) {
        this.fail(i, "replay: after the repair the contents differ");
        return false;
      }
      for (const d of this.order()) this.observeGrowth(d);
      return true;
    };
    if (m.key < 0 || file === undefined) {
      this.emit(`{"i":${i},"op":"replay","kind":${goQuote(kind)},"skip":true}`);
      return reopen(); // a plaintext file binds no pointer
    }
    const image = this.image(m)!;
    let classified: { kinds: Map<string, number[]>; deps: Set<number> };
    try {
      classified = pointerKinds(image, this.credential(m));
    } catch (e) {
      this.fail(i, `replay: classifying the pages of version ${m.version}: ${errText(e)}`);
      return false;
    }
    const cands: { page: number; versions: Uint8Array[] }[] = [];
    for (const pg of classified.kinds.get(kind) ?? []) {
      const versions = file.replayVersions(pg);
      if (versions.length > 0) cands.push({ page: pg, versions });
    }
    if (cands.length === 0) {
      this.emit(`{"i":${i},"op":"replay","kind":${goQuote(kind)},"skip":true}`);
      return reopen();
    }
    const step = BigInt(i);
    const c =
      cands[Number(decide(this.seed, LANE_REPLAY_PAGE, step, 0n, 0n) % BigInt(cands.length))]!;
    const older =
      c.versions[
        Number(decide(this.seed, LANE_REPLAY_VERSION, step, 0n, 0n) % BigInt(c.versions.length))
      ]!;
    // The generation in the other meta slot, the one a fallback recovers.
    let other = 0n;
    const ps = this.pageSize;
    for (let slot = 0; slot < 2; slot++) {
      const mt = parseCommitMeta(image.subarray(slot * ps, (slot + 1) * ps), ps, 0xffff_ffff);
      if (mt !== null && mt.txid < m.version && mt.txid > other) other = mt.txid;
    }
    const isDep = classified.deps.has(c.page);
    const flip = file.replace(c.page, older);
    const what = `replay of ${kind} page ${c.page}`;
    let outcome = "";
    const detected = (e: unknown): boolean => {
      const code = errCode(e);
      if (code !== "XX001") {
        this.fail(i, `${what}: ${code}, not XX001: ${errText(e)}`);
        return false;
      }
      outcome = "XX001";
      return true;
    };
    let got = 0n;
    let openErr: unknown = null;
    try {
      this.openProc(0);
    } catch (e) {
      if (e instanceof SimDeadlock) throw e;
      openErr = e;
    }
    if (openErr !== null) {
      if (!detected(openErr)) return false;
    } else {
      got = versionOf(this.database);
      let dg: string | null;
      try {
        dg = this.committedDigest(m);
      } catch (e) {
        this.digestErr = e;
        dg = null;
      }
      this.dropProc(0);
      if (dg === null) {
        if (!detected(this.digestErr)) return false;
      } else if (got === m.version && dg === m.lastDigest && !isDep) {
        // The rows are right, so the replayed page was not on their path: the image checker reads
        // every other reachable page and must find it. (A page the manifest depends on must have
        // failed the manifest's digest instead.)
        let checkErr: unknown = null;
        try {
          checkImage(this.image(m)!, got, this.credential(m));
        } catch (e) {
          checkErr = e;
        }
        if (checkErr === null) {
          this.fail(i, `${what} went undetected`);
          return false;
        }
        if (!detected(checkErr)) return false;
      } else if (got < m.version && got === other && isDep && m.inHistory(got, dg)) {
        // The manifest's digest of the page fails, so recovery falls back (validated-cow.md §1) to an
        // intact older generation.
        try {
          checkImage(this.image(m)!, got, this.credential(m));
        } catch (e) {
          this.fail(
            i,
            `${what}: the fallback generation ${got} fails the image checker: ${errText(e)}`,
          );
          return false;
        }
        outcome = "fallback";
      } else {
        this.fail(
          i,
          `${what}: version ${got} read back with contents (digest ${dg}) the replay must not ` +
            `produce (manifest dependency: ${isDep}, other slot ${other})`,
        );
        return false;
      }
    }
    this.fs.processDeath();
    file.repair([flip]);
    if (!reopen()) return false;
    if (outcome === "fallback") {
      this.emit(
        `{"i":${i},"op":"replay","kind":${goQuote(kind)},"page":${c.page},"outcome":"fallback","version":${got}}`,
      );
    } else {
      this.emit(
        `{"i":${i},"op":"replay","kind":${goQuote(kind)},"page":${c.page},"outcome":"XX001"}`,
      );
    }
    return true;
  }

  // stepRestore is `restore <j>` (§8.3 *Restores*, S13): main's j-th newest successful backup (the
  // oldest if there are fewer) is copied over it as a host would, with every process ended cleanly.
  // Main is then that backup's generation, under the key it had then; the history above it is
  // forgotten, so every later commit diverges from the one the backup was taken in.
  private stepRestore(i: number, j: number): boolean {
    for (const pid of this.livePids()) {
      try {
        this.closeProc(pid);
      } catch (e) {
        if (!isEngineError(e)) throw e;
        this.fail(i, "close: " + errText(e));
        return false;
      }
    }
    this.closeFlushed();
    this.fs.processDeath();
    const m = this.main();
    const k = Math.max(this.backupsOK.length - j, 0);
    if (this.backupsOK.length === 0 || !this.fs.files.has(this.backupsOK[k]!.file)) {
      // Nothing to restore: the processes still end, as the generator's model expects.
      try {
        this.open();
      } catch (e) {
        this.fail(i, "restore: reopen failed: " + errText(e));
        return false;
      }
      for (const d of this.order()) this.observeGrowth(d);
      this.emit(`{"i":${i},"op":"restore","skip":true}`);
      return true;
    }
    const b = this.backupsOK[k]!;
    this.fs.restore(b.file, m.file);
    for (const v of [...m.history.keys()]) if (v >= b.version) m.history.delete(v);
    m.addHistory(b.version, b.digest);
    m.version = b.version;
    m.lastDigest = b.digest;
    m.floor = b.version;
    m.maxAttempted = b.version;
    m.key = b.key;
    m.keyChange = null;
    m.ownerLost = false;
    m.shrinkDue = false;
    try {
      this.open();
    } catch (e) {
      this.fail(i, "restore: open failed: " + errText(e));
      return false;
    }
    const v = versionOf(this.database);
    const dg = this.committedDigest(m);
    if (dg === null || v !== b.version || dg !== b.digest) {
      this.fail(
        i,
        `restore: main opened at version ${v} (digest ${dg ?? ""}), want the backup's ${b.version} ` +
          `(digest ${b.digest})`,
      );
      return false;
    }
    for (const d of this.order()) this.observeGrowth(d);
    this.emit(`{"i":${i},"op":"restore","backup":${b.n},"version":${v},"digest":${goQuote(dg)}}`);
    return true;
  }

  // livePids lists the running processes in order.
  private livePids(): number[] {
    return [...this.procs.keys()].sort((a, b) => a - b);
  }

  // sessionsOf lists pid's open sessions in name order.
  private sessionsOf(pid: number): string[] {
    const sids: string[] = [];
    for (const [sid, ss] of this.sessions) if (ss.pid === pid) sids.push(sid);
    return sids.sort(compareUtf8);
  }

  // closeProc ends process pid cleanly: its sessions end (a writer rolls back) and its Database
  // closes, releasing its locks.
  private closeProc(pid: number): void {
    for (const sid of this.sessionsOf(pid)) {
      const ss = this.sessions.get(sid)!;
      if (ss.write) {
        try {
          ss.s.rollback();
        } catch (e) {
          if (!isEngineError(e)) throw e;
        }
      } else closeQuietly(ss.s);
      this.sessions.delete(sid);
    }
    try {
      this.procs.get(pid)!.db.close();
    } finally {
      this.locks?.release(pid);
      this.procs.delete(pid);
      if (this.service) this.net.kill(pid);
    }
  }

  // dropProc abandons process pid as a crash does: its sessions and Database vanish without closing,
  // and the kernel releases its locks.
  private dropProc(pid: number): void {
    const p = this.procs.get(pid);
    if (p !== undefined) {
      // A dead owner may take every version above the floor with it (§8.2): under synchronous = off
      // the simulated process crash may drop writes of the step that acknowledged a commit, and under
      // either mode a generation it adopted but never stabilized (validated-cow.md §3) may be dropped
      // by a failed stabilization sync. Each database it owned (main or an attachment under the
      // service) has its own floor.
      for (const d of this.dbs.values()) {
        const c = serviceCoreOf(p.db, d);
        if (c !== null && c.service !== null) d.ownerLost = true;
      }
    }
    for (const sid of this.sessionsOf(pid)) this.sessions.delete(sid);
    this.locks?.release(pid);
    this.procs.delete(pid);
    if (this.cur === pid) this.db = null;
    // The kernel closes a dead process's sockets.
    if (this.service) this.net.kill(pid);
  }

  // observe checks the version and contents a process sees of main when it begins (S5): in a shared
  // trace another process may have committed — or died mid-commit, leaving a complete generation
  // another process adopts — so the version may be newer than the last this runner saw, but never
  // older, and its contents must be a generation the history records.
  private observe(i: number, who: string, v: bigint, d: string | null): boolean {
    return this.observeDB(i, this.main(), who, v, d);
  }

  // observeDB is observe for database m: under the page service every attachment is shared too.
  private observeDB(i: number, m: SimDB, who: string, v: bigint, d: string | null): boolean {
    const what = m.name === "main" ? "" : " of " + m.name;
    if (d === null) {
      this.fail(i, `${who}: version ${v}${what} is unreadable: ${errText(this.digestErr)}`);
    } else if (v < m.version && (!m.ownerLost || v < m.floor)) {
      this.fail(i, `${who} sees version ${v}${what} after version ${m.version} was published`);
    } else if (v > m.maxAttempted) {
      this.fail(
        i,
        `${who} sees version ${v}${what}, which was never attempted (latest attempted ${m.maxAttempted})`,
      );
    } else if (!m.inHistory(v, d)) {
      this.fail(
        i,
        `${who} sees version ${v}${what} with contents (digest ${d}) no transaction produced`,
      );
    }
    if (this.violation !== "") return false;
    m.version = v;
    m.lastDigest = d!;
    m.ownerLost = false;
    return true;
  }

  // selectProc makes pid the process running the step.
  private selectProc(pid: number): boolean {
    const p = this.procs.get(pid);
    if (p === undefined) return false;
    this.cur = pid;
    this.db = p.db;
    return true;
  }

  // stepPid is the process a step runs in: a session's own, an explicit one, or the lowest running.
  private stepPid(st: SimStep): number | null {
    switch (st.kind) {
      case "open":
      case "spawn":
      case "exit":
      case "kill":
        return st.pid;
      case "backup":
        if (st.pid >= 0) return st.pid;
        break;
      case "on":
      case "commit":
      case "rollback":
      case "close":
        return this.sessions.get(st.sid)?.pid ?? null;
    }
    const pids = this.livePids();
    return pids.length > 0 ? pids[0]! : null;
  }

  // stepSpawn starts a process (S5) and checks what it sees.
  private stepSpawn(i: number, pid: number): void {
    if (this.procs.has(pid)) {
      // The generator cannot know a fault killed the owner and that p0 restarted since.
      this.emit(`{"i":${i},"op":"spawn","pid":${pid},"skip":true}`);
      return;
    }
    try {
      this.openProc(pid);
    } catch (e) {
      if (e instanceof SimDeadlock) throw e;
      const code = errCode(e);
      if (code.startsWith("non-engine") || code === "XX001") {
        this.fail(i, `spawn p${pid}: ${errText(e)}`);
        return;
      }
      this.emit(`{"i":${i},"op":"spawn","pid":${pid},"error":${goQuote(code)}}`);
      return;
    }
    const v = versionOf(this.database);
    const d = this.committedDigest(this.main());
    if (!this.observe(i, `spawned p${pid}`, v, d)) return;
    const versions = new Map<string, bigint>();
    for (const name of this.attachedNames()) {
      const a = this.dbs.get(name)!;
      if (this.dbVersion(a) === 0n) continue;
      const adg = this.committedDigest(a);
      if (!this.observeDB(i, a, `spawned p${pid}`, this.dbVersion(a), adg)) return;
      versions.set(name, this.dbVersion(a));
    }
    this.emit(`{"i":${i},"op":"spawn","pid":${pid},"version":${v}${this.versionsJSON(versions)}}`);
  }
}

function closeQuietly(s: Session): void {
  try {
    s.close();
  } catch (e) {
    if (!isEngineError(e)) throw e;
  }
}

// simQuery runs sql and folds its rendered rows, sorted (row order is not what this harness
// tests), into an FNV-1a hash. Engine errors propagate to the caller.
function simQuery(
  s: Session,
  sql: string,
): { n: number; affected: number; hash: string; cost: bigint } {
  const rows = s.query(sql);
  const rendered: string[] = [];
  let cost: bigint;
  let affected: number | null;
  try {
    for (const row of rows) {
      const cells: string[] = [];
      for (const v of row) cells.push(s.render(v));
      rendered.push(cells.join("\x1f"));
    }
    cost = rows.cost;
    affected = rows.rowsAffected;
  } finally {
    rows.close();
  }
  rendered.sort(compareUtf8);
  const h = new Fnv64();
  h.update(utf8(rendered.join("\x1e")));
  return { n: rendered.length, affected: affected ?? -1, hash: h.hex(), cost };
}

// freeListOf reads the free list the meta slot holding version v persists, from a file image.
function freeListOf(image: Uint8Array | null, ps: number, v: bigint): number[] | null {
  if (image === null) return null;
  for (let slot = 0; slot < 2; slot++) {
    const off = slot * ps;
    if (off + ps > image.length) continue;
    const m = parseCommitMeta(image.subarray(off, off + ps), ps, 0xffff_ffff);
    if (m === null || m.txid !== v) continue;
    try {
      return readFreeListChain(
        (p) => {
          if ((p + 1) * ps > image.length) throw new Error("short image");
          return image.subarray(p * ps, (p + 1) * ps);
        },
        m.freeListHead,
        m.pageCount,
      );
    } catch {
      return null;
    }
  }
  return null;
}

// imageHash folds the logical image — the pages below the high-water — into FNV-1a 64 (§8.4).
// Preallocated tails past the high-water are host policy and excluded.
function imageHash(image: Uint8Array, pages: number, pageSize: number): string {
  const n = Math.min(pages * pageSize, image.length);
  return fnvHex(image.subarray(0, n));
}
